'use strict';

const store = require('./store');
const seed = require('./seed');
const auth = require('./auth');
const orgs = require('./orgs');
const teams = require('./teams');
const repos = require('./repos');

module.exports = {
  init(ctx) {
    const created = store.init(ctx);
    if (created) seed.run(ctx);
  },
  async handle(req, res, ctx) {
    if (await auth.handle(req, res, ctx)) return true;
    if (await orgs.handle(req, res, ctx)) return true;
    if (await teams.handle(req, res, ctx)) return true;
    if (await repos.handle(req, res, ctx)) return true;
    return false;
  },
};

