'use strict';

const store = require('./store');

function isValidUsername(username) {
  return (
    typeof username === 'string' &&
    username.length >= 1 &&
    username.length <= 39 &&
    /^[a-z0-9]+(-[a-z0-9]+)*$/.test(username)
  );
}

function isValidEmail(raw) {
  const email = String(raw || '').trim();
  if (email.length > 254) return false;
  const at = email.indexOf('@');
  if (at <= 0 || at !== email.lastIndexOf('@')) return false;
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  if (!local || local.includes(' ') || !domain || domain.includes(' ')) return false;
  if (!domain.includes('.') || domain.startsWith('.') || domain.endsWith('.')) return false;
  return domain.split('.').every((part) => part.length > 0);
}

function isValidPassword(password) {
  return (
    typeof password === 'string' &&
    password.length >= 12 &&
    password.length <= 128 &&
    /[A-Z]/.test(password) &&
    /[a-z]/.test(password) &&
    /\d/.test(password) &&
    /[^A-Za-z0-9]/.test(password) &&
    !/\s/.test(password)
  );
}

function publicUser(user) {
  if (!user) return null;
  const { passwordHash, ...pub } = user;
  return pub;
}

function currentUser(ctx) {
  const token = ctx.cookies.session;
  if (!token) return null;
  const session = store.findSessionByToken(token);
  if (!session) return null;
  return store.findUserById(session.userId) || null;
}

async function register(req, res, ctx) {
  const body = await ctx.readBody(req);
  const errors = {};

  const username = typeof body.username === 'string' ? body.username : '';
  const email = typeof body.email === 'string' ? body.email.trim() : '';
  const password = typeof body.password === 'string' ? body.password : '';
  const confirmPassword = typeof body.confirmPassword === 'string' ? body.confirmPassword : '';
  const terms = body.terms === true || body.terms === 'on' || body.terms === 'true';

  if (!username) {
    errors.username = 'Username is required';
  } else if (!isValidUsername(username)) {
    errors.username = 'Username format is invalid';
  } else if (store.findUserByUsername(username)) {
    errors.username = 'Username already exists';
  }

  if (!email) {
    errors.email = 'Email is required';
  } else if (!isValidEmail(email)) {
    errors.email = 'Email format is invalid';
  } else if (store.findUserByEmail(email)) {
    errors.email = 'Email already exists';
  }

  if (!isValidPassword(password)) {
    errors.password = 'Password requirements are not satisfied';
  }

  if (password && confirmPassword !== password) {
    errors.confirmPassword = 'Passwords do not match';
  }

  if (!terms) {
    errors.terms = 'Agree to terms is required';
  }

  if (Object.keys(errors).length > 0) {
    return ctx.sendJson(res, 400, { errors });
  }

  const user = store.createUser({
    username,
    email,
    passwordHash: store.hashPassword(password),
    verified: true,
  });
  store.save(ctx);
  return ctx.sendJson(res, 201, { user: publicUser(user) });
}

async function signin(req, res, ctx) {
  const body = await ctx.readBody(req);
  const identifier = typeof body.identifier === 'string' ? body.identifier : '';
  const password = typeof body.password === 'string' ? body.password : '';

  const user = store.findUserByUsername(identifier) || store.findUserByEmail(identifier);
  if (!user || !user.verified || store.hashPassword(password) !== user.passwordHash) {
    return ctx.sendJson(res, 401, { error: 'Invalid credentials' });
  }

  const session = store.createSession(user.id);
  store.save(ctx);
  ctx.setCookie(res, 'session', session.token, { maxAge: 7 * 24 * 60 * 60, httpOnly: true });
  return ctx.sendJson(res, 200, { user: publicUser(user) });
}

async function signout(req, res, ctx) {
  const token = ctx.cookies.session;
  if (token) {
    store.deleteSession(token);
    store.save(ctx);
  }
  ctx.clearCookie(res, 'session');
  return ctx.sendJson(res, 204, {});
}

async function me(req, res, ctx) {
  const user = currentUser(ctx);
  if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });
  return ctx.sendJson(res, 200, { user: publicUser(user) });
}

async function forgot(req, res, ctx) {
  await ctx.readBody(req);
  return ctx.sendJson(res, 200, { code: '123456' });
}

async function reset(req, res, ctx) {
  const body = await ctx.readBody(req);
  const email = typeof body.email === 'string' ? body.email.trim() : '';
  const code = typeof body.code === 'string' ? body.code : '';
  const password = typeof body.password === 'string' ? body.password : '';
  const confirmPassword = typeof body.confirmPassword === 'string' ? body.confirmPassword : '';

  if (code !== '123456') {
    return ctx.sendJson(res, 400, { error: 'Verification code is invalid' });
  }

  const user = store.findUserByEmail(email);
  if (!user) return ctx.sendJson(res, 400, { error: 'Account not found' });

  if (!isValidPassword(password)) {
    return ctx.sendJson(res, 400, { error: 'Password requirements are not satisfied' });
  }
  if (password !== confirmPassword) {
    return ctx.sendJson(res, 400, { error: 'Passwords do not match' });
  }

  store.updateUser(user.id, { passwordHash: store.hashPassword(password) });
  store.deleteSessionsByUser(user.id);
  store.save(ctx);
  return ctx.sendJson(res, 200, { message: 'Password updated' });
}

async function changePassword(req, res, ctx) {
  const user = currentUser(ctx);
  if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });

  const body = await ctx.readBody(req);
  const currentPassword = typeof body.currentPassword === 'string' ? body.currentPassword : '';
  const newPassword = typeof body.newPassword === 'string' ? body.newPassword : '';
  const confirmPassword = typeof body.confirmPassword === 'string' ? body.confirmPassword : '';

  if (!currentPassword) {
    return ctx.sendJson(res, 400, { error: 'Current password is required' });
  }
  if (store.hashPassword(currentPassword) !== user.passwordHash) {
    return ctx.sendJson(res, 400, { error: 'Current password is incorrect' });
  }
  if (!isValidPassword(newPassword)) {
    return ctx.sendJson(res, 400, { error: 'Password requirements are not satisfied' });
  }
  if (newPassword !== confirmPassword) {
    return ctx.sendJson(res, 400, { error: 'Password confirmation does not match' });
  }

  store.updateUser(user.id, { passwordHash: store.hashPassword(newPassword) });
  store.deleteSessionsByUser(user.id, ctx.cookies.session);
  store.save(ctx);
  return ctx.sendJson(res, 200, { message: 'Password updated' });
}

async function handle(req, res, ctx) {
  if (ctx.method === 'POST' && ctx.path === '/api/auth/register') return await register(req, res, ctx);
  if (ctx.method === 'POST' && ctx.path === '/api/auth/signin') return await signin(req, res, ctx);
  if (ctx.method === 'POST' && ctx.path === '/api/auth/signout') return await signout(req, res, ctx);
  if (ctx.method === 'GET' && ctx.path === '/api/auth/me') return await me(req, res, ctx);
  if (ctx.method === 'POST' && ctx.path === '/api/auth/forgot') return await forgot(req, res, ctx);
  if (ctx.method === 'POST' && ctx.path === '/api/auth/reset') return await reset(req, res, ctx);
  if (ctx.method === 'POST' && ctx.path === '/api/auth/change-password') return await changePassword(req, res, ctx);
  return false;
}

module.exports = { handle };

