'use strict';

const store = require('./store');

function routeParam(match, name) {
  if (!match) return null;
  if (match[name] !== undefined) return match[name];
  if (match.params && match.params[name] !== undefined) return match.params[name];
  return null;
}

function isValidOrgName(name) {
  return (
    typeof name === 'string' &&
    name.length >= 1 &&
    name.length <= 39 &&
    /^[a-z0-9]+(-[a-z0-9]+)*$/.test(name)
  );
}

function currentUser(ctx) {
  const token = ctx.cookies.session;
  if (!token) return null;
  const session = store.findSessionByToken(token);
  if (!session) return null;
  return store.findUserById(session.userId) || null;
}

function isOrgMember(user, orgId) {
  return !!user && !!store.findOrgMembership(orgId, user.id);
}

function isOrgOwner(user, orgId) {
  if (!user) return false;
  const membership = store.findOrgMembership(orgId, user.id);
  return !!membership && membership.role === 'owner';
}

async function listOrganizations(req, res, ctx) {
  const user = currentUser(ctx);
  if (!user) {
    const organizations = store
      .listAllOrganizations()
      .map((org) => ({ ...org, role: null }));
    return ctx.sendJson(res, 200, { organizations });
  }

  const memberships = store.listOrgMembershipsByUser(user.id);
  const organizations = memberships
    .map((membership) => {
      const org = store.findOrgById(membership.organizationId);
      return org ? { ...org, role: membership.role } : null;
    })
    .filter(Boolean);

  return ctx.sendJson(res, 200, { organizations });
}

function findOrgByDisplayName(displayName) {
  const value = String(displayName || '').trim().toLowerCase();
  const db = store.getDb();
  return db.organizations.find((o) => o.displayName.toLowerCase() === value) || null;
}

async function createOrganization(req, res, ctx) {
  const user = currentUser(ctx);
  if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });

  const body = await ctx.readBody(req);
  const rawName = typeof body.name === 'string' ? body.name : '';
  const name = rawName.trim().toLowerCase();
  const displayName = typeof body.displayName === 'string' ? body.displayName.trim() : '';

  const errors = {};
  if (store.findOrgByName(name) || (rawName.trim() && findOrgByDisplayName(rawName))) {
    errors.name = 'Organization name already exists';
  } else if (!isValidOrgName(name)) {
    errors.name = 'Organization name format is invalid';
  }
  if (!displayName || displayName.length > 100) {
    errors.displayName = 'Display name is required';
  }

  if (Object.keys(errors).length > 0) {
    return ctx.sendJson(res, 400, { errors });
  }

  const organization = store.createOrganization(name, displayName);
  store.createOrgMembership(organization.id, user.id, 'owner');
  store.save(ctx);
  return ctx.sendJson(res, 201, { organization });
}

async function getOrganization(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });

  const user = currentUser(ctx);
  const membership = user ? store.findOrgMembership(org.id, user.id) : null;
  return ctx.sendJson(res, 200, { organization: org, role: membership ? membership.role : null });
}

async function listPeople(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });

  const user = currentUser(ctx);
  if (!isOrgMember(user, org.id)) {
    return ctx.sendJson(res, 403, { error: 'Forbidden' });
  }

  const members = store
    .listOrgMemberships(org.id)
    .map((membership) => {
      const member = store.findUserById(membership.userId);
      return member
        ? { id: member.id, username: member.username, email: member.email, role: membership.role }
        : null;
    })
    .filter(Boolean);

  return ctx.sendJson(res, 200, { members });
}

async function addMember(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });

  const user = currentUser(ctx);
  if (!isOrgOwner(user, org.id)) {
    return ctx.sendJson(res, 403, { error: 'Forbidden' });
  }

  const body = await ctx.readBody(req);
  const identifier = typeof body.identifier === 'string' ? body.identifier.trim() : '';
  const target = store.findUserByUsername(identifier) || store.findUserByEmail(identifier);
  if (!target) return ctx.sendJson(res, 400, { error: 'Account not found' });
  if (store.findOrgMembership(org.id, target.id)) {
    return ctx.sendJson(res, 400, { error: 'Account is already a member' });
  }

  const role = body.role === 'owner' ? 'owner' : 'member';
  const membership = store.createOrgMembership(org.id, target.id, role);
  store.save(ctx);
  return ctx.sendJson(res, 201, {
    membership: { ...membership, username: target.username },
  });
}

async function removeMember(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const userId = routeParam(match, 'userId');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });

  const user = currentUser(ctx);
  if (!isOrgOwner(user, org.id)) {
    return ctx.sendJson(res, 403, { error: 'Forbidden' });
  }

  const membership = store.findOrgMembership(org.id, userId);
  if (!membership) return ctx.sendJson(res, 404, { error: 'Member not found' });

  if (membership.role === 'owner' && store.countOrgOwners(org.id) <= 1) {
    return ctx.sendJson(res, 400, { error: 'Organization must have at least one owner' });
  }

  store.removeOrgMember(org.id, userId);
  store.save(ctx);
  return ctx.sendJson(res, 204, {});
}

async function handle(req, res, ctx) {
  let match;

  if ((match = ctx.match('GET', '/api/organizations'))) {
    return await listOrganizations(req, res, ctx);
  }
  if ((match = ctx.match('POST', '/api/organizations'))) {
    return await createOrganization(req, res, ctx);
  }
  if ((match = ctx.match('GET', '/api/organizations/:orgName'))) {
    return await getOrganization(req, res, ctx, match);
  }
  if ((match = ctx.match('GET', '/api/organizations/:orgName/people'))) {
    return await listPeople(req, res, ctx, match);
  }
  if ((match = ctx.match('POST', '/api/organizations/:orgName/people'))) {
    return await addMember(req, res, ctx, match);
  }
  if ((match = ctx.match('DELETE', '/api/organizations/:orgName/people/:userId'))) {
    return await removeMember(req, res, ctx, match);
  }

  return false;
}

module.exports = { handle };

