'use strict';

const store = require('./store');

const ROLES = ['read', 'triage', 'write', 'maintain', 'admin'];

function routeParam(match, name) {
  if (!match) return null;
  if (match[name] !== undefined) return match[name];
  if (match.params && match.params[name] !== undefined) return match.params[name];
  return null;
}

function currentUser(ctx) {
  const token = ctx.cookies.session;
  if (!token) return null;
  const session = store.findSessionByToken(token);
  if (!session) return null;
  return store.findUserById(session.userId) || null;
}

function getUserRepoRoles(userId, repo) {
  const roles = new Set();
  if (!userId) return roles;

  const membership = store.findOrgMembership(repo.organizationId, userId);
  if (membership && membership.role === 'owner') roles.add('admin');

  const direct = store.findRepoGrant(repo.id, 'user', userId);
  if (direct) roles.add(direct.role);

  for (const tm of store.listTeamMembershipsForUserInOrg(userId, repo.organizationId)) {
    const grant = store.findRepoGrant(repo.id, 'team', tm.teamId);
    if (grant) roles.add(grant.role);
  }

  return roles;
}

function isRepoAccessible(userId, repo) {
  if (repo.visibility === 'public') return true;
  return getUserRepoRoles(userId, repo).size > 0;
}

function canManage(userId, repo) {
  return getUserRepoRoles(userId, repo).has('admin');
}

function serializeRepo(repo) {
  const org = store.findOrgById(repo.organizationId);
  return {
    id: repo.id,
    name: repo.name,
    organizationId: repo.organizationId,
    organizationName: org ? org.name : repo.organizationId,
    visibility: repo.visibility,
    description: repo.description || '',
    updatedAt: repo.updatedAt || repo.createdAt || null,
  };
}

async function listRepositories(req, res, ctx) {
  const user = currentUser(ctx);
  const repositories = store
    .listAllRepositories()
    .filter((repo) => isRepoAccessible(user ? user.id : null, repo))
    .map(serializeRepo);
  return ctx.sendJson(res, 200, { repositories });
}

async function listOrgRepositories(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });

  const user = currentUser(ctx);
  const isMember = user ? !!store.findOrgMembership(org.id, user.id) : false;
  const repositories = store
    .listRepositoriesByOrg(org.id)
    .filter((repo) => {
      if (repo.visibility === 'public') return true;
      if (!user) return false;
      if (isMember) return true;
      return isRepoAccessible(user.id, repo);
    })
    .map(serializeRepo);
  return ctx.sendJson(res, 200, { repositories });
}

async function getRepository(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const repoName = routeParam(match, 'repoName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Repository not found' });
  const repo = store.findRepository(org.id, repoName);
  if (!repo) return ctx.sendJson(res, 404, { error: 'Repository not found' });

  const user = currentUser(ctx);
  if (!isRepoAccessible(user ? user.id : null, repo)) {
    if (!user) {
      return ctx.sendJson(res, 404, { error: 'Repository not found' });
    }
    return ctx.sendJson(res, 403, { error: 'Access denied' });
  }

  return ctx.sendJson(res, 200, { repository: serializeRepo(repo) });
}

async function listAccess(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const repoName = routeParam(match, 'repoName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Repository not found' });
  const repo = store.findRepository(org.id, repoName);
  if (!repo) return ctx.sendJson(res, 404, { error: 'Repository not found' });

  const user = currentUser(ctx);
  if (!user || !canManage(user.id, repo)) {
    return ctx.sendJson(res, 403, { error: 'Forbidden' });
  }

  const grants = store.listRepoGrants(repo.id).map((grant) => {
    let granteeName = grant.granteeId;
    if (grant.granteeType === 'user') {
      const grantee = store.findUserById(grant.granteeId);
      if (grantee) granteeName = grantee.username;
    } else {
      const team = store.findTeamById(grant.granteeId);
      if (team) granteeName = team.name;
    }
    return {
      id: grant.id,
      repositoryId: grant.repositoryId,
      granteeType: grant.granteeType,
      granteeId: grant.granteeId,
      granteeName,
      role: grant.role,
    };
  });

  return ctx.sendJson(res, 200, { grants });
}

async function addGrant(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const repoName = routeParam(match, 'repoName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Repository not found' });
  const repo = store.findRepository(org.id, repoName);
  if (!repo) return ctx.sendJson(res, 404, { error: 'Repository not found' });

  const user = currentUser(ctx);
  if (!user || !canManage(user.id, repo)) {
    return ctx.sendJson(res, 403, { error: 'Forbidden' });
  }

  const body = await ctx.readBody(req);
  const role = typeof body.role === 'string' ? body.role.toLowerCase() : '';
  if (!ROLES.includes(role)) {
    return ctx.sendJson(res, 400, { error: 'Role is invalid' });
  }

  let granteeType;
  let granteeId;

  if (body.granteeType === 'user') {
    const identifier = body.granteeId || body.username || body.identifier;
    const grantee = store.findUserById(identifier) || store.findUserByUsername(identifier) || store.findUserByEmail(identifier);
    if (!grantee) return ctx.sendJson(res, 400, { error: 'User not found' });
    if (!store.findOrgMembership(org.id, grantee.id)) {
      return ctx.sendJson(res, 400, { error: 'User is not an organization member' });
    }
    granteeType = 'user';
    granteeId = grantee.id;
  } else if (body.granteeType === 'team') {
    const team = store.findTeam(org.id, body.granteeId) || store.findTeamById(body.granteeId);
    if (!team || team.organizationId !== org.id) {
      return ctx.sendJson(res, 400, { error: 'Team not found' });
    }
    granteeType = 'team';
    granteeId = team.id;
  } else {
    return ctx.sendJson(res, 400, { error: 'Grantee type is invalid' });
  }

  const existing = store.findRepoGrant(repo.id, granteeType, granteeId);
  if (existing) {
    existing.role = role;
    store.save(ctx);
    return ctx.sendJson(res, 200, { grant: existing });
  }

  const grant = store.createRepoGrant(repo.id, granteeType, granteeId, role);
  store.save(ctx);
  return ctx.sendJson(res, 201, { grant });
}

async function removeGrant(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const repoName = routeParam(match, 'repoName');
  const grantId = routeParam(match, 'grantId');
  const org = store.findOrgByName(orgName);
