  const userIds = {};

  const accounts = [
    ['alice-dev', 'alice.dev@example.test'],
    ['org-owner', 'org-owner@example.test'],
    ['existing-member', 'existing-member@example.test'],
    ['new-member', 'new-member@example.test'],
    ['org-member', 'org-member@example.test'],
    ['protected-member', 'protected-member@example.test'],
