    ['bob-reviewer', 'bob-reviewer@example.test'],
    ['recovery-success', 'recovery-success@example.test'],
    ['recovery-invalid-code', 'recovery-invalid-code@example.test'],
    ['recovery-visibility', 'recovery-visibility@example.test'],
