  const memberNames = [
    'existing-member',
    'org-member',
    'protected-member',
    'repo-admin',
    'bob-reviewer',
  ];
  for (const name of memberNames) {
    store.createOrgMembership(acme.id, userIds[name], 'member');
  }
  store.createOrgMembership(acme.id, userIds['team-maintainer'], 'owner');

  const platformTeam = store.createTeam(acme.id, 'platform-team', null);
  const frontendTeam = store.createTeam(acme.id, 'frontend-team', platformTeam.id);
  store.createTeam(acme.id, 'frontend-child', frontendTeam.id);
