'use strict';

const crypto = require('crypto');

let db = null;

function init(ctx) {
  const existing = ctx.loadJson('db.json', null);
  if (existing && Array.isArray(existing.users) && Array.isArray(existing.sessions)) {
    db = existing;
    if (!db.meta) {
      db.meta = {
        userSeq: 1,
        orgSeq: 1,
        teamSeq: 1,
        repoSeq: 1,
        membershipSeq: 1,
        teamMembershipSeq: 1,
        grantSeq: 1,
        sessionSeq: 1,
      };
    }
    return false;
  }
  db = {
    users: [],
    sessions: [],
    organizations: [],
    orgMemberships: [],
    teams: [],
    teamMemberships: [],
    repositories: [],
    repoGrants: [],
    meta: {
      userSeq: 1,
      orgSeq: 1,
      teamSeq: 1,
      repoSeq: 1,
      membershipSeq: 1,
      teamMembershipSeq: 1,
      grantSeq: 1,
      sessionSeq: 1,
    },
  };
  return true;
}

function getDb() {
  return db;
}

function save(ctx) {
  ctx.saveJson('db.json', db);
}

function nextId(key, prefix) {
  return prefix + db.meta[key]++;
}

function hashPassword(password) {
  return crypto.createHash('sha256').update(password).digest('hex');
}

function findUserByUsername(username) {
  return db.users.find((u) => u.username === username) || null;
}

function findUserByEmail(email) {
  const value = String(email || '').trim().toLowerCase();
  return db.users.find((u) => u.email.toLowerCase() === value) || null;
}

function findUserById(id) {
  return db.users.find((u) => u.id === id) || null;
}

function createUser({ username, email, passwordHash, verified = true }) {
  const user = {
    id: nextId('userSeq', 'u'),
    username,
    email: String(email || '').trim().toLowerCase(),
    passwordHash,
    verified,
    createdAt: new Date().toISOString(),
  };
  db.users.push(user);
  return user;
}

function updateUser(id, patch) {
  const user = findUserById(id);
  if (!user) return null;
  Object.assign(user, patch);
  return user;
}

function createSession(userId) {
  const token = crypto.randomBytes(24).toString('hex');
  const session = {
    id: nextId('sessionSeq', 's'),
    token,
    userId,
    createdAt: new Date().toISOString(),
  };
  db.sessions.push(session);
  return session;
}

function findSessionByToken(token) {
  if (!token) return null;
  return db.sessions.find((s) => s.token === token) || null;
}

function deleteSession(token) {
  const before = db.sessions.length;
  db.sessions = db.sessions.filter((s) => s.token !== token);
  return db.sessions.length !== before;
}

function deleteSessionsByUser(userId, keepToken) {
  db.sessions = db.sessions.filter(
    (s) => !(s.userId === userId && s.token !== keepToken)
  );
}

function createOrganization(name, displayName) {
  const organization = {
    id: nextId('orgSeq', 'o'),
    name,
    displayName,
    createdAt: new Date().toISOString(),
  };
  db.organizations.push(organization);
  return organization;
}

function findOrgByName(name) {
  return db.organizations.find((o) => o.name === name) || null;
}

function findOrgById(id) {
  return db.organizations.find((o) => o.id === id) || null;
}

function listAllOrganizations() {
  return db.organizations.slice();
}

function createOrgMembership(organizationId, userId, role) {
  const membership = {
    id: nextId('membershipSeq', 'm'),
    organizationId,
    userId,
    role,
  };
  db.orgMemberships.push(membership);
  return membership;
}

function findOrgMembership(organizationId, userId) {
  return (
    db.orgMemberships.find(
      (m) => m.organizationId === organizationId && m.userId === userId
    ) || null
  );
}

function listOrgMemberships(organizationId) {
  return db.orgMemberships.filter((m) => m.organizationId === organizationId);
}

function listOrgMembershipsByUser(userId) {
  return db.orgMemberships.filter((m) => m.userId === userId);
}

function deleteOrgMembership(organizationId, userId) {
  const before = db.orgMemberships.length;
  db.orgMemberships = db.orgMemberships.filter(
    (m) => !(m.organizationId === organizationId && m.userId === userId)
  );
  return db.orgMemberships.length !== before;
}

function countOrgOwners(organizationId) {
  return db.orgMemberships.filter(
    (m) => m.organizationId === organizationId && m.role === 'owner'
  ).length;
}

function removeOrgMember(organizationId, userId) {
  deleteOrgMembership(organizationId, userId);

  const teamIds = new Set(
    db.teams.filter((t) => t.organizationId === organizationId).map((t) => t.id)
  );
  db.teamMemberships = db.teamMemberships.filter(
    (tm) => !(teamIds.has(tm.teamId) && tm.userId === userId)
  );

  const repoIds = new Set(
    db.repositories
      .filter((r) => r.organizationId === organizationId)
      .map((r) => r.id)
  );
  db.repoGrants = db.repoGrants.filter(
    (g) =>
      !(repoIds.has(g.repositoryId) && g.granteeType === 'user' && g.granteeId === userId)
  );
}

function createTeam(organizationId, name, parentTeamId) {
  const team = {
    id: nextId('teamSeq', 't'),
    organizationId,
    name,
    parentTeamId: parentTeamId || null,
  };
  db.teams.push(team);
  return team;
}

function findTeam(organizationId, name) {
  return (
    db.teams.find((t) => t.organizationId === organizationId && t.name === name) ||
    null
  );
}

function findTeamById(id) {
  return db.teams.find((t) => t.id === id) || null;
}

function listTeams(organizationId) {
  return db.teams.filter((t) => t.organizationId === organizationId);
}

function createTeamMembership(teamId, userId) {
  const membership = {
    id: nextId('teamMembershipSeq', 'tm'),
    teamId,
    userId,
  };
  db.teamMemberships.push(membership);
  return membership;
}

function findTeamMembership(teamId, userId) {
  return (
    db.teamMemberships.find((tm) => tm.teamId === teamId && tm.userId === userId) ||
    null
  );
}

function deleteTeamMembership(teamId, userId) {
  const before = db.teamMemberships.length;
  db.teamMemberships = db.teamMemberships.filter(
    (tm) => !(tm.teamId === teamId && tm.userId === userId)
  );
  return db.teamMemberships.length !== before;
}

function listTeamMemberships(teamId) {
