    db.teams.filter((t) => t.organizationId === organizationId).map((t) => t.id)
  );
  return db.teamMemberships.filter((tm) => tm.userId === userId && teamIds.has(tm.teamId));
}

function deleteTeamMembershipsForUserInOrg(userId, organizationId) {
  const teamIds = new Set(
    db.teams.filter((t) => t.organizationId === organizationId).map((t) => t.id)
  );
