'use strict';

const store = require('./store');

function routeParam(match, name) {
  if (!match) return null;
  if (match[name] !== undefined) return match[name];
  if (match.params && match.params[name] !== undefined) return match.params[name];
  return null;
}

function isValidTeamName(name) {
  return (
    typeof name === 'string' &&
    name.length >= 1 &&
    name.length <= 50 &&
    /^[a-z0-9]+(-[a-z0-9]+)*$/.test(name)
  );
}

function currentUser(ctx) {
  const token = ctx.cookies.session;
  if (!token) return null;
  const session = store.findSessionByToken(token);
  if (!session) return null;
  return store.findUserById(session.userId) || null;
}

function isOrgMember(user, orgId) {
  return !!user && !!store.findOrgMembership(orgId, user.id);
}

function isOrgOwner(user, orgId) {
  if (!user) return false;
  const membership = store.findOrgMembership(orgId, user.id);
  return !!membership && membership.role === 'owner';
}

function wouldCreateCycle(teamId, newParentId) {
  let current = newParentId;
  const seen = new Set();
  while (current) {
    if (current === teamId) return true;
    if (seen.has(current)) return true;
    seen.add(current);
    const team = store.findTeamById(current);
    current = team ? team.parentTeamId : null;
  }
  return false;
}

async function listTeams(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });

  const user = currentUser(ctx);
  if (!isOrgMember(user, org.id)) return ctx.sendJson(res, 403, { error: 'Forbidden' });

  const teams = store.listTeams(org.id).map((team) => ({
    id: team.id,
    name: team.name,
    organizationId: team.organizationId,
    parentTeamId: team.parentTeamId,
  }));

  return ctx.sendJson(res, 200, { teams });
}

async function createTeam(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });

  const user = currentUser(ctx);
  if (!isOrgOwner(user, org.id)) return ctx.sendJson(res, 403, { error: 'Forbidden' });

  const body = await ctx.readBody(req);
  const name = typeof body.name === 'string' ? body.name.trim().toLowerCase() : '';
  if (!isValidTeamName(name)) {
    return ctx.sendJson(res, 400, { error: 'Team name is invalid' });
  }
  if (store.findTeam(org.id, name)) {
    return ctx.sendJson(res, 400, { error: 'Team name already exists' });
  }

  let parentTeamId = null;
  if (body.parentTeamName) {
    const parent = store.findTeam(org.id, body.parentTeamName);
    if (!parent) return ctx.sendJson(res, 400, { error: 'Parent team not found' });
    parentTeamId = parent.id;
  } else if (body.parentTeamId) {
    const parent = store.findTeamById(body.parentTeamId);
    if (!parent || parent.organizationId !== org.id) {
      return ctx.sendJson(res, 400, { error: 'Parent team not found' });
    }
    parentTeamId = parent.id;
  }

  const team = store.createTeam(org.id, name, parentTeamId);
  store.save(ctx);
  return ctx.sendJson(res, 201, {
    team: {
      id: team.id,
      name: team.name,
      organizationId: team.organizationId,
      parentTeamId: team.parentTeamId,
    },
  });
}

async function updateTeamParent(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const teamName = routeParam(match, 'teamName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });
  const team = store.findTeam(org.id, teamName);
  if (!team) return ctx.sendJson(res, 404, { error: 'Team not found' });

  const user = currentUser(ctx);
  if (!isOrgOwner(user, org.id)) return ctx.sendJson(res, 403, { error: 'Forbidden' });

  const body = await ctx.readBody(req);
  let parentTeamId = null;
  const rawParent = body.parentTeamName || body.parentTeamId;
  if (rawParent) {
    let parent = null;
    if (body.parentTeamName) {
      parent = store.findTeam(org.id, body.parentTeamName);
    } else {
      parent = store.findTeamById(body.parentTeamId);
    }
    if (!parent || parent.organizationId !== org.id) {
      return ctx.sendJson(res, 400, { error: 'Team not found' });
    }
    parentTeamId = parent.id;
  }

  if (parentTeamId && wouldCreateCycle(team.id, parentTeamId)) {
    return ctx.sendJson(res, 400, { error: 'Cyclic team hierarchy is not allowed' });
  }

  team.parentTeamId = parentTeamId;
  store.save(ctx);
  return ctx.sendJson(res, 200, {
    team: {
      id: team.id,
      name: team.name,
      organizationId: team.organizationId,
      parentTeamId: team.parentTeamId,
    },
  });
}

async function getTeam(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const teamName = routeParam(match, 'teamName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });

  const user = currentUser(ctx);
  if (!isOrgMember(user, org.id)) return ctx.sendJson(res, 403, { error: 'Forbidden' });

  const team = store.findTeam(org.id, teamName);
  if (!team) return ctx.sendJson(res, 404, { error: 'Team not found' });

  const members = store
    .listTeamMemberships(team.id)
    .map((tm) => {
      const member = store.findUserById(tm.userId);
      return member
        ? { id: member.id, username: member.username, email: member.email }
        : null;
    })
    .filter(Boolean);

  const childTeams = store
    .listTeams(org.id)
    .filter((t) => t.parentTeamId === team.id)
    .map((t) => ({ id: t.id, name: t.name, parentTeamId: t.parentTeamId }));

  return ctx.sendJson(res, 200, {
    team: {
      id: team.id,
      name: team.name,
      organizationId: team.organizationId,
      parentTeamId: team.parentTeamId,
    },
    members,
    childTeams,
  });
}

async function addMember(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const teamName = routeParam(match, 'teamName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });
  const team = store.findTeam(org.id, teamName);
  if (!team) return ctx.sendJson(res, 404, { error: 'Team not found' });

  const user = currentUser(ctx);
  if (!isOrgOwner(user, org.id)) return ctx.sendJson(res, 403, { error: 'Forbidden' });

  const body = await ctx.readBody(req);
  const identifier = typeof body.identifier === 'string' ? body.identifier.trim() : '';
  const target = store.findUserByUsername(identifier) || store.findUserByEmail(identifier);
  if (!target) return ctx.sendJson(res, 400, { error: 'User not found' });
  if (!store.findOrgMembership(org.id, target.id)) {
    return ctx.sendJson(res, 400, { error: 'User is not an organization member' });
  }
  if (store.findTeamMembership(team.id, target.id)) {
    return ctx.sendJson(res, 400, { error: 'User is already a member' });
  }

  const membership = store.createTeamMembership(team.id, target.id);
  store.save(ctx);
  return ctx.sendJson(res, 201, { membership: { ...membership, username: target.username } });
}

async function removeMember(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const teamName = routeParam(match, 'teamName');
  const userId = routeParam(match, 'userId');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });
  const team = store.findTeam(org.id, teamName);
  if (!team) return ctx.sendJson(res, 404, { error: 'Team not found' });

  const user = currentUser(ctx);
  if (!isOrgOwner(user, org.id)) return ctx.sendJson(res, 403, { error: 'Forbidden' });

  if (!store.findTeamMembership(team.id, userId)) {
    return ctx.sendJson(res, 404, { error: 'Member not found' });
  }

  store.deleteTeamMembership(team.id, userId);
  store.save(ctx);
  return ctx.sendJson(res, 204, {});
}

async function addChildTeam(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const teamName = routeParam(match, 'teamName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });
  const parent = store.findTeam(org.id, teamName);
  if (!parent) return ctx.sendJson(res, 404, { error: 'Team not found' });

  const user = currentUser(ctx);
  if (!isOrgOwner(user, org.id)) return ctx.sendJson(res, 403, { error: 'Forbidden' });

  const body = await ctx.readBody(req);
  const childName = typeof body.teamName === 'string' ? body.teamName.trim().toLowerCase() : '';
  const child = store.findTeam(org.id, childName);
  if (!child) return ctx.sendJson(res, 400, { error: 'Team not found' });
  if (child.id === parent.id) {
    return ctx.sendJson(res, 400, { error: 'A team cannot be its own parent' });
  }
  if (wouldCreateCycle(child.id, parent.id)) {
    return ctx.sendJson(res, 400, { error: 'Parent team cycle is invalid' });
  }

  child.parentTeamId = parent.id;
  store.save(ctx);
  return ctx.sendJson(res, 200, {
    team: { id: child.id, name: child.name, organizationId: child.organizationId, parentTeamId: child.parentTeamId },
  });
}

async function removeChildTeam(req, res, ctx, match) {
  const orgName = routeParam(match, 'orgName');
  const teamName = routeParam(match, 'teamName');
  const childTeamName = routeParam(match, 'childTeamName');
  const org = store.findOrgByName(orgName);
  if (!org) return ctx.sendJson(res, 404, { error: 'Organization not found' });
  const parent = store.findTeam(org.id, teamName);
  if (!parent) return ctx.sendJson(res, 404, { error: 'Team not found' });

  const user = currentUser(ctx);
  if (!isOrgOwner(user, org.id)) return ctx.sendJson(res, 403, { error: 'Forbidden' });

  const child = store.findTeam(org.id, childTeamName);
  if (!child || child.parentTeamId !== parent.id) {
    return ctx.sendJson(res, 404, { error: 'Child team not found' });
  }

  child.parentTeamId = null;
  store.save(ctx);
  return ctx.sendJson(res, 204, {});
}

async function handle(req, res, ctx) {
  let match;

  if ((match = ctx.match('GET', '/api/organizations/:orgName/teams'))) {
    return await listTeams(req, res, ctx, match);
  }
  if ((match = ctx.match('POST', '/api/organizations/:orgName/teams'))) {
    return await createTeam(req, res, ctx, match);
  }
  if ((match = ctx.match('PATCH', '/api/organizations/:orgName/teams/:teamName'))) {
    return await updateTeamParent(req, res, ctx, match);
  }
  if ((match = ctx.match('GET', '/api/organizations/:orgName/teams/:teamName'))) {
    return await getTeam(req, res, ctx, match);
  }
  if ((match = ctx.match('POST', '/api/organizations/:orgName/teams/:teamName/members'))) {
    return await addMember(req, res, ctx, match);
  }
  if ((match = ctx.match('DELETE', '/api/organizations/:orgName/teams/:teamName/members/:userId'))) {
    return await removeMember(req, res, ctx, match);
  }
  if ((match = ctx.match('POST', '/api/organizations/:orgName/teams/:teamName/child-teams'))) {
    return await addChildTeam(req, res, ctx, match);
  }
  if ((match = ctx.match('DELETE', '/api/organizations/:orgName/teams/:teamName/child-teams/:childTeamName'))) {
    return await removeChildTeam(req, res, ctx, match);
  }

  return false;
}

module.exports = { handle };

