'use strict';
const crypto = require('node:crypto');
const store = require('./store');

function normalizeUsername(value) {
  return typeof value === 'string' ? value.trim().toLowerCase() : '';
}

function normalizeEmail(value) {
  return typeof value === 'string' ? value.trim().toLowerCase() : '';
}

function validateUsernameInput(value) {
  const name = typeof value === 'string' ? value.trim() : '';
  return name.length >= 1 && name.length <= 39 && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(name);
}

function validateEmail(value) {
  const email = normalizeEmail(value);
  if (!email || email.length > 254) return false;
  const at = email.indexOf('@');
  if (at <= 0 || at !== email.lastIndexOf('@')) return false;
  const domain = email.slice(at + 1);
  if (!domain.includes('.')) return false;
  const labels = domain.split('.');
  return labels.length >= 2 && labels.every((label) => label.length > 0);
}

function validatePassword(value) {
  return (
    typeof value === 'string' &&
    value.length >= 12 &&
    value.length <= 128 &&
    !/\s/.test(value) &&
    /[A-Z]/.test(value) &&
    /[a-z]/.test(value) &&
    /[0-9]/.test(value) &&
    /[^A-Za-z0-9]/.test(value)
  );
}

function createSession(username) {
  const token = crypto.randomBytes(24).toString('hex');
  store.addSession({ token, username, createdAt: new Date().toISOString() });
  return token;
}

function currentUser(ctx) {
  const token = ctx.cookies && ctx.cookies.session;
  if (!token) return null;
  const session = store.findSessionByToken(token);
  if (!session) return null;
  return store.findUserByUsername(session.username);
}

async function register(req, res, ctx) {
  const body = (await ctx.readBody(req)) || {};
  const usernameInput = typeof body.username === 'string' ? body.username.trim() : '';
  const username = normalizeUsername(usernameInput);
  const email = normalizeEmail(body.email);
  const password = typeof body.password === 'string' ? body.password : '';
  const confirmPassword = typeof body.confirmPassword === 'string' ? body.confirmPassword : '';
  const terms = body.terms === true || body.terms === 'true' || body.terms === 'on';
  const errors = {};

  if (!validateUsernameInput(usernameInput)) {
    errors.username = 'Username format is invalid';
  } else if (store.findUserByUsername(username)) {
    errors.username = 'Username already exists';
  }

  if (!validateEmail(email)) {
    errors.email = 'Email format is invalid';
  } else if (store.findUserByEmail(email)) {
    errors.email = 'Email already exists';
  }

  if (!validatePassword(password)) {
    errors.password = 'Password requirements are not satisfied';
  } else if (password !== confirmPassword) {
    errors.confirmPassword = 'Passwords do not match';
  }

  if (!terms) {
    errors.terms = 'Agree to terms is required';
  }

  if (Object.keys(errors).length > 0) {
    return ctx.sendJson(res, 400, { error: 'Registration failed', errors });
  }

  const { salt, hash } = store.createPasswordHash(password);
  store.addUser({
    username,
    email,
    passwordHash: hash,
    passwordSalt: salt,
    createdAt: new Date().toISOString(),
    verified: true,
  });

  return ctx.sendJson(res, 201, { user: { username, email } });
}

async function signin(req, res, ctx) {
  const body = (await ctx.readBody(req)) || {};
  const identifier = typeof body.identifier === 'string' ? body.identifier.trim() : '';
  const password = typeof body.password === 'string' ? body.password : '';
  const user = store.findUserByUsername(identifier) || store.findUserByEmail(identifier);

  if (!user || !store.verifyPassword(password, user)) {
    return ctx.sendJson(res, 401, { error: 'Invalid credentials' });
  }

  const token = createSession(user.username);
  ctx.setCookie(res, 'session', token, { maxAge: 60 * 60 * 24 * 7, httpOnly: true, path: '/' });
  return ctx.sendJson(res, 200, { user: { username: user.username, email: user.email } });
}

async function signout(req, res, ctx) {
  const token = ctx.cookies && ctx.cookies.session;
  if (!token || !store.findSessionByToken(token)) {
    return ctx.sendJson(res, 401, { error: 'Unauthorized' });
  }
  store.deleteSession(token);
  ctx.clearCookie(res, 'session');
  return ctx.sendJson(res, 204, null);
}

async function me(req, res, ctx) {
  const user = currentUser(ctx);
  if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });
  return ctx.sendJson(res, 200, { user: { username: user.username, email: user.email } });
}

async function changePassword(req, res, ctx) {
  const user = currentUser(ctx);
  if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });

  const body = (await ctx.readBody(req)) || {};
  store.deleteUserSessions(user.username);
  ctx.clearCookie(res, 'session');

  const currentPassword = typeof body.currentPassword === 'string' ? body.currentPassword : '';
  const newPassword = typeof body.newPassword === 'string' ? body.newPassword : '';
  const confirmPassword = typeof body.confirmPassword === 'string' ? body.confirmPassword : '';

  const errors = {};
  if (!currentPassword) {
    errors.currentPassword = 'Current password is required';
  } else if (!store.verifyPassword(currentPassword, user)) {
    errors.currentPassword = 'Current password is incorrect';
  }
  if (!validatePassword(newPassword)) {
    errors.newPassword = 'Password requirements are not satisfied';
  }
  if (newPassword !== confirmPassword) {
    errors.confirmPassword = 'Password confirmation does not match';
  }
  if (Object.keys(errors).length > 0) {
    return ctx.sendJson(res, 400, { error: 'Password not updated', errors });
  }

  const { salt, hash } = store.createPasswordHash(newPassword);
  user.passwordHash = hash;
  user.passwordSalt = salt;
  store.save();

  return ctx.sendJson(res, 200, { message: 'Password changed.' });
}

async function recoveryRequest(req, res, ctx) {
  const body = (await ctx.readBody(req)) || {};
  const email = normalizeEmail(body.email);
  const user = store.findUserByEmail(email);
  return ctx.sendJson(res, 200, { code: '123456', emailFound: !!user });
}

async function recoveryReset(req, res, ctx) {
  const body = (await ctx.readBody(req)) || {};
  const email = normalizeEmail(body.email);
  const code = typeof body.code === 'string' ? body.code : '';
  const password = typeof body.password === 'string' ? body.password : '';
  const confirmPassword = typeof body.confirmPassword === 'string' ? body.confirmPassword : '';

  if (code !== '123456') {
    return ctx.sendJson(res, 400, { error: 'Verification code is invalid' });
  }

  const user = store.findUserByEmail(email);
  if (!user) return ctx.sendJson(res, 404, { error: 'Email not found' });

  if (!validatePassword(password)) {
    return ctx.sendJson(res, 400, { error: 'Password requirements are not satisfied' });
  }
  if (password !== confirmPassword) {
    return ctx.sendJson(res, 400, { error: 'Passwords do not match' });
  }

  const { salt, hash } = store.createPasswordHash(password);
  user.passwordHash = hash;
  user.passwordSalt = salt;
  store.save();
  store.deleteUserSessions(user.username);

  return ctx.sendJson(res, 200, { message: 'Password updated.' });
}

async function handle(req, res, ctx) {
  if (ctx.match('POST', '/api/auth/register')) return await register(req, res, ctx);
  if (ctx.match('POST', '/api/auth/signin')) return await signin(req, res, ctx);
  if (ctx.method === 'GET' && ctx.path === '/api/auth/me') return await me(req, res, ctx);
  if (ctx.match('POST', '/api/auth/signout')) return await signout(req, res, ctx);
  if (ctx.match('POST', '/api/auth/password')) return await changePassword(req, res, ctx);
  if (ctx.match('POST', '/api/auth/recovery/request')) return await recoveryRequest(req, res, ctx);
  if (ctx.match('POST', '/api/auth/recovery/reset')) return await recoveryReset(req, res, ctx);
  return false;
}

module.exports = { handle, currentUser };

