async function addPerson(req, res, ctx, params) {
  const user = currentUser(ctx);
  if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });
  if (!store.isOrgOwner(params.orgName, user.username)) {
    return ctx.sendJson(res, 403, { error: 'Forbidden' });
  }

  const body = (await ctx.readBody(req)) || {};
  const identifier = typeof body.usernameOrEmail === 'string' ? body.usernameOrEmail.trim() : '';
  const role = body.role;
  if (role !== 'Member' && role !== 'Owner') {
    return ctx.sendJson(res, 400, { error: 'Role must be Member or Owner' });
  }

  const target = store.findUserByUsername(identifier) || store.findUserByEmail(identifier);
  if (!target) return ctx.sendJson(res, 404, { error: 'Account not found' });
  if (store.findMembership(params.orgName, target.username)) {
    return ctx.sendJson(res, 409, { error: 'Account is already a member' });
  }

  store.addMembership({ orgName: params.orgName, username: target.username, role });
  return ctx.sendJson(res, 201, { member: { username: target.username, role } });
}

async function removePerson(req, res, ctx, params) {
  const user = currentUser(ctx);
  if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });
  if (!store.isOrgOwner(params.orgName, user.username)) {
    return ctx.sendJson(res, 403, { error: 'Forbidden' });
  }

  const membership = store.findMembership(params.orgName, params.username);
  if (!membership) return ctx.sendJson(res, 404, { error: 'Member not found' });

  const ownerCount = store.data().memberships.filter((m) => m.orgName === params.orgName && m.role === 'Owner').length;
  if (membership.role === 'Owner' && ownerCount <= 1) {
    return ctx.sendJson(res, 409, { error: 'Cannot remove the last organization owner' });
  }

  store.clearUserOrgConnections(params.orgName, params.username);
  return ctx.sendJson(res, 204, null);
}

