  }
  return { ownerType: 'user', ownerName: ownerParam };
}

function canCreateRepository(ownerType, ownerName, user) {
  if (!user) return false;
  return store.canCreateRepository(ownerType, ownerName, user.username);
}

function isValidRepoName(name) {
  return (
    typeof name === 'string' &&
    name.length >= 1 &&
    name.length <= 100 &&
    /^[a-zA-Z0-9](?:[a-zA-Z0-9._-]*[a-zA-Z0-9])?$/.test(name)
  );
}

function isValidBranchName(name) {
  if (typeof name !== 'string' || name.length < 1 || name.length > 255) return false;
  if (!/^[A-Za-z0-9._/-]+$/.test(name)) return false;
  if (name.endsWith('/') || name.endsWith('.')) return false;
  if (name.includes('..') || name.includes('//')) return false;
  return true;
}

