const TRIAGE_ROLES = ['Triage', 'Maintain', 'Admin'];
const { computeMergeState, commitHex } = require('./mergeEligibility');

function canManagePullMetadata(db, repo, userId) {
  if (!userId) return false;
  if (repo.ownerType === 'user') {
    if (repo.ownerId === userId) return true;
    return db.repositoryRoles.some(
      (r) => r.repositoryId === repo.id && r.subjectType === 'user' && r.subjectId === userId && TRIAGE_ROLES.includes(r.role)
    );
  }
  const membership = db.memberships.find((m) => m.organizationId === repo.ownerId && m.userId === userId);
  if (membership && membership.role === 'Owner') return true;
  if (
    db.repositoryRoles.some(
      (r) => r.repositoryId === repo.id && r.subjectType === 'user' && r.subjectId === userId && TRIAGE_ROLES.includes(r.role)
    )
  ) {
    return true;
  }
  const teamIds = db.teamMemberships.filter((tm) => tm.userId === userId).map((tm) => tm.teamId);
  return db.repositoryRoles.some(
    (r) => r.repositoryId === repo.id && r.subjectType === 'team' && teamIds.includes(r.subjectId) && TRIAGE_ROLES.includes(r.role)
  );
}

function canTransitionPullStatus(db, repo, pull, user) {
  if (!user) return false;
  if (pull.authorId === user.id) return true;
  const allowed = ['Maintain', 'Admin'];
  if (repo.ownerType === 'user') {
    if (repo.ownerId === user.id) return true;
    return db.repositoryRoles.some(
      (r) => r.repositoryId === repo.id && r.subjectType === 'user' && r.subjectId === user.id && allowed.includes(r.role)
    );
  }
  const membership = db.memberships.find((m) => m.organizationId === repo.ownerId && m.userId === user.id);
  if (membership && membership.role === 'Owner') return true;
  if (
    db.repositoryRoles.some(
      (r) => r.repositoryId === repo.id && r.subjectType === 'user' && r.subjectId === user.id && allowed.includes(r.role)
    )
  ) {
    return true;
  }
  const teamIds = db.teamMemberships.filter((tm) => tm.userId === user.id).map((tm) => tm.teamId);
  return db.repositoryRoles.some(
    (r) => r.repositoryId === repo.id && r.subjectType === 'team' && teamIds.includes(r.subjectId) && allowed.includes(r.role)
  );
}

function canMergePull(db, repo, pull, user) {
  if (!user || pull.status !== 'open') return false;
  if (repo.ownerType === 'user') {
    if (repo.ownerId === user.id) return true;
  } else {
    const membership = db.memberships.find((m) => m.organizationId === repo.ownerId && m.userId === user.id);
    if (membership && membership.role === 'Owner') return true;
  }
  const allowedRoles = ['Maintain', 'Admin'];
  if (db.repositoryRoles.some((r) => r.repositoryId === repo.id && r.subjectType === 'user' && r.subjectId === user.id && allowedRoles.includes(r.role))) return true;
  const teamIds = db.teamMemberships.filter((tm) => tm.userId === user.id).map((tm) => tm.teamId);
  return db.repositoryRoles.some((r) => r.repositoryId === repo.id && r.subjectType === 'team' && teamIds.includes(r.subjectId) && allowedRoles.includes(r.role));
}

function pullToJson(db, pull, user, repo) {
  const author = db.users.find((u) => u.id === pull.authorId) || {};
  const milestone = pull.milestoneId ? db.milestones.find((m) => m.id === pull.milestoneId) || null : null;
  const canManage = user ? canManagePullMetadata(db, repo, user.id) : false;
  const canReady = user && pull.status === 'draft' && (pull.authorId === user.id || canManage);
  const canTransition = user ? canTransitionPullStatus(db, repo, pull, user) : false;
  const mergeState = computeMergeState(db, repo, pull, user);
  const activity = Array.isArray(pull.activity) ? pull.activity : [];
  const reviewers = (pull.reviewers || [])
    .map((id) => {
      const reviewer = db.users.find((u) => u.id === id);
      return reviewer ? reviewer.username : null;
    })
    .filter(Boolean);
  return {
    id: pull.id,
    number: pull.number,
    title: pull.title,
    description: pull.description || '',
    authorUsername: author.username || 'unknown',
    status: pull.status,
    baseBranch: pull.baseBranch,
    compareBranch: pull.compareBranch,
    createdAt: pull.createdAt,
    updatedAt: pull.updatedAt,
    milestone: milestone ? { id: milestone.id, title: milestone.title } : null,
