const { commitHex } = require('./mergeEligibility');

function repoRespond(db, repo, ownerNameFn) {
  const owner = ownerNameFn(repo);
  const org = repo.ownerType === 'org' ? db.organizations.find((o) => o.id === repo.ownerId) : null;
  const user = repo.ownerType === 'user' ? db.users.find((u) => u.id === repo.ownerId) : null;
  const branch = db.branches.find((b) => b.repositoryId === repo.id && b.name === repo.defaultBranch);
  const files = branch
    ? Object.keys(branch.files).map((p) => ({ path: p, name: p.split('/').pop() }))
    : [];
  let forkedFrom = null;
  if (repo.forkedFromId) {
    const source = db.repositories.find((r) => r.id === repo.forkedFromId);
    if (source) forkedFrom = { id: source.id, owner: ownerNameFn(source), name: source.name };
  }
  return {
    id: repo.id,
    ownerType: repo.ownerType,
    ownerName: owner,
    ownerDisplayName: org ? org.displayName : user ? user.username : owner,
    name: repo.name,
    description: repo.description || '',
    visibility: repo.visibility,
    defaultBranch: repo.defaultBranch,
    files,
    forkedFrom,
  };
}

function collectChain(db, branch) {
  const chain = [];
  let current = branch.commitId;
  while (current) {
    const commit = db.commits.find((c) => c.id === current);
    if (!commit) break;
    chain.unshift(commit);
    current = commit.parentId;
  }
  return chain;
}

function copyHistory(db, nextId, sourceRepo, forkRepo) {
  const branch = db.branches.find((b) => b.repositoryId === sourceRepo.id && b.name === sourceRepo.defaultBranch);
  if (!branch) return;
  const chain = collectChain(db, branch);
  const idMap = {};
  for (const commit of chain) {
    const newId = nextId('commits');
    idMap[commit.id] = newId;
    db.commits.push({
      ...commit,
      id: newId,
      repositoryId: forkRepo.id,
      parentId: commit.parentId ? idMap[commit.parentId] : null,
    });
  }
  const files = {};
  const newestId = idMap[chain[chain.length - 1].id];
  for (const [filePath, fileData] of Object.entries(branch.files || {})) {
    files[filePath] = {
      content: fileData.content,
      commitId: idMap[fileData.commitId] || newestId,
    };
  }
  db.branches.push({
    id: nextId('branches'),
    repositoryId: forkRepo.id,
    name: forkRepo.defaultBranch,
    commitId: idMap[branch.commitId],
    files,
  });
}

module.exports = {
  async handle(req, res, ctx, helpers) {
    const { method, path } = ctx;
    const { db, save, nextId, findRepo, findOrg, ownerName, getSessionUser, userCanReadRepo } = helpers;

    if (path === '/api/repositories' && method === 'POST') {
      const user = getSessionUser(ctx);
      if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });
      const body = (await ctx.readBody(req)) || {};
      const owner = String(body.owner || user.username).trim();
      const name = String(body.name || '').trim();
      const description = String(body.description || '').trim();
      const visibility = body.visibility === 'private' ? 'private' : 'public';
      const initReadme = !!body.initReadme;
      const errors = {};

      if (!name) {
        errors.name = 'Repository name is required';
      } else if (name.length > 100 || /[\/\\]/.test(name)) {
        errors.name = 'Repository name format is invalid';
      }

      let ownerType = null;
      let ownerId = null;
      if (!errors.name) {
        const org = findOrg(owner);
        if (org) {
          const membership = db.memberships.find((x) => x.organizationId === org.id && x.userId === user.id);
          if (!membership || membership.role !== 'Owner') {
            errors.owner = 'You do not have permission to create repositories in this namespace';
          } else {
            ownerType = 'org';
            ownerId = org.id;
            if (db.repositories.some((r) => r.ownerType === 'org' && r.ownerId === org.id && r.name === name)) {
              errors.name = 'Repository name already exists';
            }
          }
        } else {
          const targetUser = db.users.find((u) => u.username === owner);
          if (!targetUser || targetUser.id !== user.id) {
            errors.owner = 'You do not have permission to create repositories in this namespace';
          } else {
            ownerType = 'user';
            ownerId = user.id;
            if (db.repositories.some((r) => r.ownerType === 'user' && r.ownerId === user.id && r.name === name)) {
              errors.name = 'Repository name already exists';
            }
          }
        }
      }

      if (Object.keys(errors).length) {
        return ctx.sendJson(res, 400, { error: 'Validation failed', errors });
      }

      const repo = {
        id: nextId('repositories'),
        ownerType,
        ownerId,
        name,
        description,
        visibility,
        defaultBranch: 'main',
        forkedFromId: null,
        createdAt: Date.now(),
      };
      db.repositories.push(repo);

      if (initReadme) {
        const commitId = nextId('commits');
        db.commits.push({
          id: commitId,
          repositoryId: repo.id,
          parentId: null,
          authorId: user.id,
          message: 'Initial commit',
          timestamp: Date.now(),
          changes: [{ path: 'README.md', oldContent: null, newContent: `# ${name}\n` }],
        });
        db.branches.push({
          id: nextId('branches'),
          repositoryId: repo.id,
          name: 'main',
          commitId,
          files: { 'README.md': { content: `# ${name}\n`, commitId } },
        });
      }

      save();
      return ctx.sendJson(res, 201, { repository: repoRespond(db, repo, ownerName) });
    }

    let match = ctx.match(method, '/api/repositories/:owner/:repo/forks');
    if (match && method === 'POST') {
      const sourceRepo = findRepo(match.owner, match.repo);
      if (!sourceRepo) return ctx.sendJson(res, 404, { error: 'Repository not found' });
      const user = getSessionUser(ctx);
      if (!user) return ctx.sendJson(res, 401, { error: 'Unauthorized' });
      if (!userCanReadRepo(sourceRepo, user.id)) {
        return ctx.sendJson(res, 403, { error: 'Access denied' });
      }

      const body = (await ctx.readBody(req)) || {};
      const namespace = String(body.namespace || body.owner || user.username).trim();
      const name = String(body.name || '').trim();
      const errors = {};

      if (!name) {
        errors.name = 'Repository name is required';
      } else if (name.length > 100 || /[\/\\]/.test(name)) {
        errors.name = 'Repository name format is invalid';
      }

      let ownerType = null;
      let ownerId = null;
      const org = findOrg(namespace);
      if (org) {
        const membership = db.memberships.find((x) => x.organizationId === org.id && x.userId === user.id);
        if (!membership || membership.role !== 'Owner') {
          errors.owner = 'You do not have permission to create repositories in this namespace';
        } else {
          ownerType = 'org';
          ownerId = org.id;
          if (db.repositories.some((r) => r.ownerType === 'org' && r.ownerId === org.id && r.name === name)) {
            errors.name = 'Repository name already exists';
          }
        }
      } else {
        const targetUser = db.users.find((u) => u.username === namespace);
        if (!targetUser || targetUser.id !== user.id) {
          errors.owner = 'You do not have permission to create repositories in this namespace';
        } else {
          ownerType = 'user';
          ownerId = user.id;
          if (db.repositories.some((r) => r.ownerType === 'user' && r.ownerId === user.id && r.name === name)) {
            errors.name = 'Repository name already exists';
          }
        }
      }

      if (Object.keys(errors).length) {
        return ctx.sendJson(res, 400, { error: 'Validation failed', errors });
      }

      const visibility =
        sourceRepo.visibility === 'private'
          ? 'private'
          : body.visibility === 'private'
            ? 'private'
            : 'public';

      const forkRepo = {
        id: nextId('repositories'),
        ownerType,
        ownerId,
        name,
        description: sourceRepo.description || '',
        visibility,
        defaultBranch: sourceRepo.defaultBranch,
        forkedFromId: sourceRepo.id,
        createdAt: Date.now(),
      };
      db.repositories.push(forkRepo);
      copyHistory(db, nextId, sourceRepo, forkRepo);
      save();
      return ctx.sendJson(res, 201, { repository: repoRespond(db, forkRepo, ownerName) });
    }

    match = ctx.match(method, '/api/repositories/:owner/:repo/commits');
    if (match && method === 'GET') {
      const repo = findRepo(match.owner, match.repo);
      if (!repo) return ctx.sendJson(res, 404, { error: 'Repository not found' });
      const user = getSessionUser(ctx);
      if (!userCanReadRepo(repo, user ? user.id : null)) {
        if (user) return ctx.sendJson(res, 403, { error: 'Access denied' });
        return ctx.sendJson(res, 404, { error: 'Repository not found' });
      }
      const branchName = ctx.query.get('branch') || repo.defaultBranch;
      const branch = db.branches.find((b) => b.repositoryId === repo.id && b.name === branchName);
      if (!branch) return ctx.sendJson(res, 200, { commits: [] });

      const pathFilter = ctx.query.get('path');
      const items = collectChain(db, branch)
        .slice()
        .reverse()
        .map((c) => ({
          id: String(c.id),
          sha: commitHex(c.id),
          message: c.message,
          authorUsername: (db.users.find((u) => u.id === c.authorId) || {}).username || 'unknown',
          timestamp: c.timestamp,
          parentId: c.parentId ? String(c.parentId) : null,
          changes: c.changes || [],
        }))
        .filter((c) => !pathFilter || c.changes.some((ch) => ch.path === pathFilter));

      return ctx.sendJson(res, 200, { commits: items });
    }

    return false;
  },
};

