  await page.getByRole('radio', { name: h.exact('Private') }).check();
  await page.getByRole('checkbox', { name: h.exact('Add a README file') }).check();
  await page.getByRole('button', { name: h.exact('Create repository') }).click();
  // Overview page assertions
  await expect(page.getByRole('heading', { name: `repo-owner/${repoName}` })).toBeVisible();
  await expect(page.getByText('Private', { exact: true })).toBeVisible();
  await expect(page.getByRole('link', { name: h.exact('README.md') })).toBeVisible();
  await expect(page.getByText('Repository created by Playwright')).toBeVisible();
  // Commit history contains one initialization commit
  await page.getByRole('link', { name: h.exact('Commits') }).click();
