test('REQ-6-5 #1: Merge an Eligible Pull Request - Scenario 1', async ({ page }) => {
  // Sign in as maintainer and navigate to the repository PR list
  await signInAsMaintainer(page);
  // Open the eligible PR
  await openPR(page, 'Mergeable onboarding PR');

  // Assert the merge method is the only one available
  await expect(page.getByText('Create a merge commit')).toBeVisible();

  const mergeButton = page.getByRole('button', { name: h.exact('Merge pull request') });
  await expect(mergeButton).toBeVisible();
  await expect(mergeButton).toBeEnabled();

  // Click the merge button, then confirm in the dialog
  await mergeButton.click();
  await h.click(page, 'Confirm merge');

  // Assert the PR shows Merged, the merger, and a commit identifier
  await h.expectText(page, 'Merged');
  await h.expectText(page, 'pr-maintainer');
  const commitTextLocator = page.locator('text=/[0-9a-f]{7,40}/').first();
  await expect(commitTextLocator).toBeVisible();
  const commitText = await commitTextLocator.textContent();

  // Refresh and verify the merged state and commit remain
  await page.reload();
  await h.expectText(page, 'Merged');
  await h.expectText(page, 'pr-maintainer');
  await expect(page.locator('text=/[0-9a-f]{7,40}/').first()).toBeVisible();

  // Navigate to the Code page (main branch) and verify the merge commit appears in history
  await h.click(page, 'Code');
  // Ensure we are on the main branch (default) then open commits
  await h.click(page, 'Commits');
  await h.expectText(page, commitText.trim());
});

