'use strict';

const store = require('./store');
const formulas = require('./formulas');
const validations = require('./validations');
const history = require('./history');

function normalizeValue(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed !== '' && /^[+-]?(\d+\.?\d*|\.\d+)$/.test(trimmed)) {
      const n = Number(trimmed);
      if (Number.isFinite(n)) return n;
    }
    return value;
  }
  return String(value);
}

function parseCoord(coord) {
  const m = /^([A-Z]+)([1-9][0-9]*)$/.exec(String(coord).toUpperCase());
  if (!m) return null;
  let col = 0;
  for (let i = 0; i < m[1].length; i++) {
    col = col * 26 + (m[1].charCodeAt(i) - 64);
  }
  return { col, row: parseInt(m[2], 10) };
}

async function handle(req, res, ctx) {
  const putMatch = ctx.match('PUT', '/api/workbooks/:id/sheets/:sheetId/cells/:cellId');
  const rangeMatch = ctx.match('PATCH', '/api/workbooks/:id/sheets/:sheetId/range');
  if (!putMatch && !rangeMatch) return false;

  const match = putMatch || rangeMatch;
  const body = (await ctx.readBody(req)) || {};

  const workbook = store.getWorkbook(match.id);
  if (!workbook) {
    return ctx.sendJson(res, 404, { error: 'Workbook not found' });
  }

  const sheet = (workbook.sheets || []).find((s) => s.id === match.sheetId);
  if (!sheet) {
    return ctx.sendJson(res, 404, { error: 'Worksheet not found' });
  }

  const cells = sheet.cells || (sheet.cells = {});

  if (putMatch) {
    if (!('value' in body)) {
      return ctx.sendJson(res, 400, { error: 'value is required' });
    }

    const coord = putMatch.cellId.toUpperCase();
    if (!/^([A-Z]+)([1-9][0-9]*)$/.test(coord)) {
      return ctx.sendJson(res, 400, { error: 'Invalid cell coordinate' });
    }

    const raw = body.value;

    const isFormula = typeof raw === 'string' && raw.trim().startsWith('=');
    const isEmpty = raw === '' || raw === null || raw === undefined;
    let normalized;
    if (!isFormula && !isEmpty) {
      normalized = normalizeValue(raw);
      const validationError = validations.checkValue(sheet, coord, normalized);
      if (validationError) {
        const existingCell = cells[coord];
        if (existingCell && existingCell.f === undefined) {
          const existingError = validations.checkValue(sheet, coord, existingCell.v);
          if (existingError) {
            delete cells[coord];
            formulas.recalcSheet(sheet);
            workbook.updatedAt = new Date().toISOString();
            store.save();
            return ctx.sendJson(res, 400, { error: validationError, workbook });
          }
        }
        return ctx.sendJson(res, 400, { error: validationError });
      }
    }
    history.push(workbook);
    if (isFormula) {
      cells[coord] = { f: raw.trim(), v: formulas.evaluate(sheet, raw.trim()) };
    } else if (isEmpty) {
      delete cells[coord];
    } else {
      cells[coord] = { v: normalized };
    }

    formulas.recalcSheet(sheet);
    workbook.updatedAt = new Date().toISOString();
    store.save();
    return ctx.sendJson(res, 200, { workbook });
  }

  if (typeof body.start !== 'string' || !body.start.trim()) {
    return ctx.sendJson(res, 400, { error: 'Starting cell is required' });
  }
  const start = parseCoord(body.start);
  if (!start) {
    return ctx.sendJson(res, 400, { error: 'Invalid start cell' });
  }

  const values = body.values;
  if (!Array.isArray(values) || values.length === 0) {
    return ctx.sendJson(res, 400, { error: 'Paste data is required' });
  }
  for (let r = 0; r < values.length; r++) {
    if (!Array.isArray(values[r])) {
      return ctx.sendJson(res, 400, { error: 'Paste data must be a rectangular grid' });
    }
  }

