function shiftRangeString(range, at, count, op) {
  if (!range || typeof range !== 'string') return range;
  const parts = range.split(':');
  if (parts.length < 2) {
    return shiftColInCoord(parts[0], at, count, op) || range;
  }
  const start = shiftColInCoord(parts[0], at, count, op);
  const end = shiftColInCoord(parts[1], at, count, op);
  if (start && end) return start + ':' + end;
  return null;
}

function insertColumns(workbook, sheet, at, count) {
  count = count || 1;
  if (at < 1) at = 1;

  const newCells = {};
  for (const coord of Object.keys(sheet.cells || {})) {
    const rc = parseCoord(coord);
    if (!rc) continue;
    const newCol = rc.col >= at ? rc.col + count : rc.col;
    newCells[colName(newCol) + rc.row] = sheet.cells[coord];
  }
  sheet.cells = newCells;
  sheet.colCount = (sheet.colCount || 26) + count;

  for (const coord of Object.keys(sheet.cells)) {
    const cell = sheet.cells[coord];
    if (cell && cell.f) {
      const adj = adjustFormulaForColumnChange(cell.f, at, count, 'insert');
      if (!adj.invalid) cell.f = adj.text;
    }
  }

  if (Array.isArray(sheet.validations)) {
    for (const v of sheet.validations) {
      const shifted = shiftRangeString(v.range, at, count, 'insert');
      if (shifted) v.range = shifted;
    }
  }

  if (sheet.sort && sheet.sort.range) {
    const shifted = shiftRangeString(sheet.sort.range, at, count, 'insert');
    if (shifted) sheet.sort.range = shifted;
  }
  if (sheet.filter && sheet.filter.range) {
    const shifted = shiftRangeString(sheet.filter.range, at, count, 'insert');
    if (shifted) sheet.filter.range = shifted;
  }

  if (sheet.selectedCell) {
    const rc = parseCoord(sheet.selectedCell);
    if (rc && rc.col >= at) {
      sheet.selectedCell = colName(rc.col + count) + rc.row;
    }
  }
  if (sheet.selection) {
    const shiftSel = (coord) => {
      const rc = parseCoord(coord);
      if (!rc) return coord;
      return colName(rc.col >= at ? rc.col + count : rc.col) + rc.row;
    };
    sheet.selection.start = shiftSel(sheet.selection.start);
    sheet.selection.end = shiftSel(sheet.selection.end);
  }

  if (Array.isArray(workbook.pivotTables)) {
    for (const p of workbook.pivotTables) {
      if (p.sourceSheetId === sheet.id) {
        const shifted = shiftRangeString(p.sourceRange, at, count, 'insert');
        if (shifted) p.sourceRange = shifted;
      }
