function deleteColumns(workbook, sheet, at, count) {
  count = count || 1;
  if (at < 1) at = 1;
  const end = Math.min(at + count - 1, sheet.colCount || 26);

  const newCells = {};
  for (const coord of Object.keys(sheet.cells || {})) {
    const rc = parseCoord(coord);
    if (!rc) continue;
    if (rc.col >= at && rc.col <= end) continue;
    const newCol = rc.col > end ? rc.col - (end - at + 1) : rc.col;
    newCells[colName(newCol) + rc.row] = sheet.cells[coord];
  }
  sheet.cells = newCells;
  sheet.colCount = Math.max(1, (sheet.colCount || 26) - (end - at + 1));

  for (const coord of Object.keys(sheet.cells)) {
    const cell = sheet.cells[coord];
    if (cell && cell.f) {
      const adj = adjustFormulaForColumnChange(cell.f, at, end - at + 1, 'delete');
      if (adj.invalid) {
        cell.v = '#REF!';
        cell._invalidRef = true;
      } else {
        cell.f = adj.text;
      }
    }
  }

  if (Array.isArray(sheet.validations)) {
    sheet.validations = sheet.validations.filter((v) => {
      const shifted = shiftRangeString(v.range, at, end - at + 1, 'delete');
      if (!shifted) return false;
      v.range = shifted;
      return true;
    });
  }

  if (sheet.sort && sheet.sort.range) {
    const shifted = shiftRangeString(sheet.sort.range, at, end - at + 1, 'delete');
    if (shifted) sheet.sort.range = shifted;
    else sheet.sort = null;
  }
  if (sheet.filter && sheet.filter.range) {
    const shifted = shiftRangeString(sheet.filter.range, at, end - at + 1, 'delete');
    if (shifted) sheet.filter.range = shifted;
    else sheet.filter = null;
  }

  if (sheet.selectedCell) {
    const rc = parseCoord(sheet.selectedCell);
    if (rc) {
      if (rc.col >= at && rc.col <= end) {
        sheet.selectedCell = 'A1';
      } else if (rc.col > end) {
        sheet.selectedCell = colName(rc.col - (end - at + 1)) + rc.row;
      }
    }
  }
  if (sheet.selection) {
    const shiftSel = (coord) => {
      const rc = parseCoord(coord);
      if (!rc) return coord;
      if (rc.col >= at && rc.col <= end) return null;
      return colName(rc.col > end ? rc.col - (end - at + 1) : rc.col) + rc.row;
    };
    const selStart = shiftSel(sheet.selection.start);
    const selEnd = shiftSel(sheet.selection.end);
    if (selStart && selEnd) {
      sheet.selection.start = selStart;
      sheet.selection.end = selEnd;
    } else {
      sheet.selection = { start: 'A1', end: 'A1' };
    }
  }

  if (Array.isArray(workbook.pivotTables)) {
    for (const p of workbook.pivotTables) {
      if (p.sourceSheetId === sheet.id) {
        const shifted = shiftRangeString(p.sourceRange, at, end - at + 1, 'delete');
        if (shifted) p.sourceRange = shifted;
        else p._invalidSource = true;
      }
    }
  }

  formulas.recalcSheet(sheet);
}

module.exports = { insertColumns, deleteColumns };

