'use strict';

const store = require('./store');
const history = require('./history');

const CONDITIONS = new Set(['Text contains', 'Greater than', 'Before', 'Is empty', 'Is not empty']);

function cleanCriteria(value) {
  const out = {};
  if (value && typeof value === 'object') {
    if (Array.isArray(value.values)) out.values = value.values.map(String);
    if (typeof value.condition === 'string' && value.condition) out.condition = value.condition;
    if (value.value !== undefined && value.value !== null && value.value !== '') out.value = value.value;
  }
  return out;
}

async function handle(req, res, ctx) {
  let m;

  if ((m = ctx.match('PUT', '/api/workbooks/:id/sheets/:sheetId/filter'))) {
    const body = (await ctx.readBody(req)) || {};
    if (typeof body.range !== 'string' || !body.range.trim()) {
      return ctx.sendJson(res, 400, { error: 'Range is required' });
    }
    const workbook = store.getWorkbook(m.id);
    if (!workbook) {
      return ctx.sendJson(res, 404, { error: 'Workbook not found' });
    }
    const sheet = (workbook.sheets || []).find((s) => s.id === m.sheetId);
    if (!sheet) {
      return ctx.sendJson(res, 404, { error: 'Worksheet not found' });
    }

    const range = body.range.trim().toUpperCase();
    const criteria = cleanCriteria(body.criteria);
    if (criteria.condition && !CONDITIONS.has(criteria.condition)) {
      return ctx.sendJson(res, 400, { error: 'Invalid filter condition' });
    }

    history.push(workbook);
    if (
      !body.column ||
      typeof body.column !== 'string' ||
      !body.column.trim() ||
      !sheet.filter ||
      sheet.filter.range !== range
    ) {
      sheet.filter = { range, criteria: {} };
    }
    if (body.column && typeof body.column === 'string' && body.column.trim()) {
      sheet.filter.criteria[body.column.trim()] = criteria;
    } else {
      sheet.filter.criteria = criteria;
    }
    workbook.updatedAt = new Date().toISOString();
    store.save();
    return ctx.sendJson(res, 200, { workbook });
  }

  if ((m = ctx.match('DELETE', '/api/workbooks/:id/sheets/:sheetId/filter'))) {
    const workbook = store.getWorkbook(m.id);
    if (!workbook) {
      return ctx.sendJson(res, 404, { error: 'Workbook not found' });
    }
    const sheet = (workbook.sheets || []).find((s) => s.id === m.sheetId);
    if (!sheet) {
      return ctx.sendJson(res, 404, { error: 'Worksheet not found' });
    }
    history.push(workbook);
    sheet.filter = null;
    workbook.updatedAt = new Date().toISOString();
    store.save();
    return ctx.sendJson(res, 200, { workbook });
  }

  return false;
}

module.exports = { handle };

