'use strict';

function formulaError(message) {
  const err = new Error(message);
  err.formulaError = true;
  return err;
}

const ERROR_VALUES = /^#(DIV\/0!|REF!|NAME\?|ERROR!|VALUE!)$/;

function isErrorValue(value) {
  return typeof value === 'string' && ERROR_VALUES.test(value);
}

function columnLettersToNumber(letters) {
  let n = 0;
  for (let i = 0; i < letters.length; i++) {
    n = n * 26 + (letters.charCodeAt(i) - 64);
  }
  return n;
}

function columnName(n) {
  let name = '';
  let value = n;
  while (value > 0) {
    const rem = (value - 1) % 26;
    name = String.fromCharCode(65 + rem) + name;
    value = Math.floor((value - 1) / 26);
  }
  return name;
}

function isCellRef(word) {
  return /^\$?[A-Za-z]{1,3}\$?[1-9][0-9]*$/.test(word);
}

function cellRC(coord) {
  const m = /^\$?([A-Za-z]+)\$?([1-9][0-9]*)$/.exec(coord);
  if (!m) return null;
  return { row: parseInt(m[2], 10), col: columnLettersToNumber(m[1].toUpperCase()) };
}

function cellValue(sheet, coord) {
  const rc = cellRC(coord);
  if (!rc) throw formulaError('#VALUE!');
  if (rc.row < 1 || rc.row > (sheet.rowCount || 0) || rc.col < 1 || rc.col > (sheet.colCount || 0)) {
    throw formulaError('#REF!');
  }
  const cell = (sheet.cells || {})[columnName(rc.col) + rc.row];
  if (!cell || cell.v === undefined) return 0;
  return cell.v;
}

function toNumber(value) {
  if (isErrorValue(value)) throw formulaError(value);
  if (typeof value === 'number') return value;
  if (typeof value === 'boolean') return value ? 1 : 0;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed === '') return 0;
    const n = Number(trimmed);
