    case 'MAX': {
      if (values.length === 0) throw formulaError('#VALUE!');
      return Math.max(...values);
    }
    case 'MIN': {
      if (values.length === 0) throw formulaError('#VALUE!');
      return Math.min(...values);
    }
    default:
      throw formulaError('#NAME?');
  }
}

function add(a, b) {
  return toNumber(a) + toNumber(b);
}
function subtract(a, b) {
  return toNumber(a) - toNumber(b);
}
function multiply(a, b) {
  return toNumber(a) * toNumber(b);
}
function divide(a, b) {
  const right = toNumber(b);
  if (right === 0) throw formulaError('#DIV/0!');
  return toNumber(a) / right;
}

function rcInBounds(rc, sheet) {
  return !!rc && rc.row >= 1 && rc.row <= (sheet.rowCount || 0) && rc.col >= 1 && rc.col <= (sheet.colCount || 0);
}

function collectRefs(sheet, formula) {
  const refs = new Set();
  if (typeof formula !== 'string' || !formula.startsWith('=')) return refs;
  const re = /\$?[A-Za-z]{1,3}\$?[1-9][0-9]*(?::\$?[A-Za-z]{1,3}\$?[1-9][0-9]*)?/g;
