    const token = m[0].replace(/\$/g, '').toUpperCase();
    if (token.includes(':')) {
      const parts = token.split(':');
      const a = cellRC(parts[0]);
      const b = cellRC(parts[1]);
      if (!rcInBounds(a, sheet) || !rcInBounds(b, sheet)) continue;
      const startRow = Math.min(a.row, b.row);
      const endRow = Math.max(a.row, b.row);
      const startCol = Math.min(a.col, b.col);
      const endCol = Math.max(a.col, b.col);
      for (let r = startRow; r <= endRow; r++) {
        for (let c = startCol; c <= endCol; c++) {
          refs.add(columnName(c) + r);
        }
      }
    } else {
      const rc = cellRC(token);
      if (rcInBounds(rc, sheet)) refs.add(columnName(rc.col) + rc.row);
    }
  }
  return refs;
}

function markCycles(sheet) {
  const cyclic = new Set();
  if (!sheet || !sheet.cells) return cyclic;
  const state = {};
  const stack = [];
  const formulaCoords = Object.keys(sheet.cells).filter((coord) => {
    const cell = sheet.cells[coord];
    return cell && typeof cell.f === 'string';
  });

  function visit(coord) {
    if (state[coord] === 2) return;
    if (state[coord] === 1) {
      const pos = stack.indexOf(coord);
      if (pos !== -1) {
        for (let i = pos; i < stack.length; i++) cyclic.add(stack[i]);
      }
      return;
    }
    state[coord] = 1;
    stack.push(coord);
    const cell = sheet.cells[coord];
    if (cell && typeof cell.f === 'string') {
      for (const ref of collectRefs(sheet, cell.f)) {
        const refCell = sheet.cells[ref];
        if (refCell && typeof refCell.f === 'string') visit(ref);
      }
    }
    stack.pop();
    state[coord] = 2;
  }

  for (const coord of formulaCoords) visit(coord);
