  if (!sheet || !sheet.cells) return;
  const cyclic = markCycles(sheet);
  for (const coord of cyclic) {
    const cell = sheet.cells[coord];
    if (cell) cell.v = '#REF!';
  }
  for (let pass = 0; pass < 20; pass++) {
