'use strict';

const store = require('./store');

function ensureHistory(workbook) {
  if (!workbook.history || typeof workbook.history !== 'object') {
    workbook.history = { undo: [], redo: [] };
  }
  if (!Array.isArray(workbook.history.undo)) workbook.history.undo = [];
  if (!Array.isArray(workbook.history.redo)) workbook.history.redo = [];
}

function captureWorkbook(workbook) {
  return {
    name: workbook.name,
    activeSheetId: workbook.activeSheetId,
    updatedAt: workbook.updatedAt,
    sheets: JSON.parse(JSON.stringify(workbook.sheets || [])),
    pivotTables: JSON.parse(JSON.stringify(workbook.pivotTables || [])),
  };
}

function restoreWorkbook(workbook, snapshot) {
  workbook.name = snapshot.name;
  workbook.activeSheetId = snapshot.activeSheetId;
  workbook.sheets = snapshot.sheets;
  workbook.pivotTables = snapshot.pivotTables;
}

function push(workbook) {
  ensureHistory(workbook);
  workbook.history.undo.push(captureWorkbook(workbook));
  workbook.history.redo = [];
}

function undo(workbook) {
  ensureHistory(workbook);
  if (workbook.history.undo.length === 0) return false;
  workbook.history.redo.push(captureWorkbook(workbook));
  const snapshot = workbook.history.undo.pop();
  restoreWorkbook(workbook, snapshot);
  workbook.updatedAt = new Date().toISOString();
  return true;
}

function redo(workbook) {
  ensureHistory(workbook);
  if (workbook.history.redo.length === 0) return false;
  workbook.history.undo.push(captureWorkbook(workbook));
  const snapshot = workbook.history.redo.pop();
  restoreWorkbook(workbook, snapshot);
  workbook.updatedAt = new Date().toISOString();
  return true;
}

async function handle(req, res, ctx) {
  const undoMatch = ctx.match('POST', '/api/workbooks/:id/undo');
  if (undoMatch) {
    const workbook = store.getWorkbook(undoMatch.id);
    if (!workbook) {
      return ctx.sendJson(res, 404, { error: 'Workbook not found' });
    }
    if (!undo(workbook)) {
      return ctx.sendJson(res, 400, { error: 'Nothing to undo' });
    }
    store.save();
    return ctx.sendJson(res, 200, { workbook });
  }

  const redoMatch = ctx.match('POST', '/api/workbooks/:id/redo');
