const store = require('./store');
const formulas = require('./formulas');

function colName(n) {
  return store.columnName(n);
}

function parseCoord(coord) {
  const m = /^([A-Z]+)([1-9][0-9]*)$/.exec(String(coord).toUpperCase());
  if (!m) return null;
  let col = 0;
  for (let i = 0; i < m[1].length; i++) {
    col = col * 26 + (m[1].charCodeAt(i) - 64);
  }
  return { col, row: parseInt(m[2], 10) };
}

function adjustFormulaForRowChange(formula, at, count, op) {
  if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
    return { text: formula, invalid: false };
  }
  let invalid = false;
  const refRegex = /\$?[A-Za-z]{1,3}\$?[1-9][0-9]*/g;
  const text = formula.replace(refRegex, (ref) => {
    const m = /^(\$?)([A-Za-z]{1,3})(\$?)([1-9][0-9]*)$/.exec(ref);
    if (!m) return ref;
    const rowAbs = m[3] !== '';
    let col = 0;
    for (let i = 0; i < m[2].length; i++) col = col * 26 + (m[2].charCodeAt(i) - 64);
    const row = parseInt(m[4], 10);
    let newRow = row;
    if (op === 'insert') {
      if (row >= at && !rowAbs) newRow = row + count;
    } else {
      if (row >= at && row < at + count && !rowAbs) {
        invalid = true;
        return ref;
      }
      if (row >= at + count && !rowAbs) newRow = row - count;
    }
    return m[1] + m[2] + (m[3] || '') + newRow;
