function shiftRowInCoord(coord, at, count, op) {
  const rc = parseCoord(coord);
  if (!rc) return coord;
  let row = rc.row;
  if (op === 'insert') {
    if (row >= at) row += count;
  } else {
    if (row >= at && row < at + count) return null;
    if (row >= at + count) row -= count;
  }
  return colName(rc.col) + row;
}

function shiftRangeString(range, at, count, op) {
  if (!range || typeof range !== 'string') return range;
  const parts = range.split(':');
  if (parts.length < 2) {
    return shiftRowInCoord(parts[0], at, count, op) || range;
  }
  const start = shiftRowInCoord(parts[0], at, count, op);
