    const rc = parseCoord(coord);
    if (!rc) continue;
    const newRow = rc.row >= at ? rc.row + count : rc.row;
    newCells[colName(rc.col) + newRow] = sheet.cells[coord];
  }
  sheet.cells = newCells;
  sheet.rowCount = (sheet.rowCount || 30) + count;

