    const shifted = shiftRangeString(sheet.sort.range, at, count, 'insert');
    if (shifted) sheet.sort.range = shifted;
  }
  if (sheet.filter && sheet.filter.range) {
    const shifted = shiftRangeString(sheet.filter.range, at, count, 'insert');
    if (shifted) sheet.filter.range = shifted;
  }

