      }
    }
  }
  if (sheet.selection) {
    const shiftSel = (coord) => {
      const rc = parseCoord(coord);
      if (!rc) return coord;
      if (rc.row >= at && rc.row <= end) return null;
      return colName(rc.col) + (rc.row > end ? rc.row - (end - at + 1) : rc.row);
    };
    const selStart = shiftSel(sheet.selection.start);
    const selEnd = shiftSel(sheet.selection.end);
    if (selStart && selEnd) {
      sheet.selection.start = selStart;
      sheet.selection.end = selEnd;
    } else {
      sheet.selection = { start: 'A1', end: 'A1' };
    }
  }

