    for (const p of workbook.pivotTables) {
      if (p.sourceSheetId === sheet.id) {
        const shifted = shiftRangeString(p.sourceRange, at, end - at + 1, 'delete');
        if (shifted) p.sourceRange = shifted;
      }
    }
  }

  recalcSheet(sheet);
}

