    if (!workbook) {
      return ctx.sendJson(res, 404, { error: 'Workbook not found' });
    }
    const name =
      typeof body.name === 'string' && body.name.trim()
        ? body.name.trim()
        : nextSheetName(workbook);
    const sheet = {
      id: store.makeId('sheet'),
      name,
      selectedCell: 'A1',
      selection: { start: 'A1', end: 'A1' },
      rowCount: 30,
      colCount: 26,
      cells: {},
      validations: [],
      sort: null,
      filter: null,
    };
    history.push(workbook);
    workbook.sheets.push(sheet);
    workbook.activeSheetId = sheet.id;
    workbook.updatedAt = new Date().toISOString();
    store.save();
    return ctx.sendJson(res, 201, { workbook });
  }

