function columnName(n) {
  let name = '';
  let value = n;
  while (value > 0) {
    const rem = (value - 1) % 26;
    name = String.fromCharCode(65 + rem) + name;
    value = Math.floor((value - 1) / 26);
  }
  return name;
}

function init(context) {
  ctx = context;
  data = context.loadJson('store.json', null);
  if (!data || !Array.isArray(data.workbooks) || data.workbooks.length === 0) {
    data = seed.create();
    save();
  }
  if (data && Array.isArray(data.workbooks)) {
    let changed = false;
    for (const workbook of data.workbooks) {
      if (!Array.isArray(workbook.sheets)) continue;
      for (const sheet of workbook.sheets) {
        if (typeof sheet.selectedCell !== 'string' || !sheet.selectedCell) {
          sheet.selectedCell = 'A1';
        }
        if (!sheet.selection || typeof sheet.selection.start !== 'string' || typeof sheet.selection.end !== 'string') {
          sheet.selection = { start: sheet.selectedCell || 'A1', end: sheet.selectedCell || 'A1' };
