function save() {
  if (ctx && data) ctx.saveJson('store.json', data);
}

function getData() {
  return data;
}

function getWorkbook(id) {
  if (!data) return null;
  return data.workbooks.find((wb) => wb.id === id) || null;
}

function listWorkbooks() {
  if (!data) return [];
  return data.workbooks.map((wb) => ({
    id: wb.id,
    name: wb.name,
    updatedAt: wb.updatedAt,
    sheetCount: Array.isArray(wb.sheets) ? wb.sheets.length : 0,
    activeSheetId: wb.activeSheetId,
  }));
}

function makeId(prefix) {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function createWorkbook(name) {
  const now = new Date().toISOString();
  const sheetId = makeId('sheet');
  const workbook = {
    id: makeId('wb'),
    name,
    createdAt: now,
    updatedAt: now,
    activeSheetId: sheetId,
    history: { undo: [], redo: [] },
    pivotTables: [],
    sheets: [
