        id: sheetId,
        name: 'Sheet1',
        selectedCell: 'A1',
        selection: { start: 'A1', end: 'A1' },
        rowCount: 30,
        colCount: 26,
        cells: {},
        validations: [],
        sort: null,
        filter: null,
      },
    ],
  };
  data.workbooks.push(workbook);
  save();
  return workbook;
}

function createWorkbookFromCSV(name, rows) {
  const now = new Date().toISOString();
  const sheetId = makeId('sheet');
  const safeRows = Array.isArray(rows) ? rows : [];
  const rowCount = Math.max(1, safeRows.length);
  const colCount = Math.max(
    1,
    safeRows.reduce((max, row) => Math.max(max, Array.isArray(row) ? row.length : 0), 0)
  );
  const cells = {};

  safeRows.forEach((row, rIndex) => {
    if (!Array.isArray(row)) return;
    row.forEach((value, cIndex) => {
      const text = value === null || value === undefined ? '' : String(value);
      if (text === '') return;
      cells[columnName(cIndex + 1) + (rIndex + 1)] = { v: text };
    });
