  const workbook = {
    id: makeId('wb'),
    name,
    createdAt: now,
    updatedAt: now,
    activeSheetId: sheetId,
    history: { undo: [], redo: [] },
    pivotTables: [],
    sheets: [
      {
        id: sheetId,
        name: 'Sheet1',
        selectedCell: 'A1',
        selection: { start: 'A1', end: 'A1' },
        rowCount,
        colCount,
        cells,
        validations: [],
        sort: null,
        filter: null,
      },
    ],
  };

  data.workbooks.push(workbook);
  save();
  return workbook;
}

module.exports = {
  init,
  save,
  getData,
  getWorkbook,
  listWorkbooks,
