    col: columnLettersToNumber(m[1]),
    row: parseInt(m[2], 10),
  };
}

function parseRange(range) {
  if (typeof range !== 'string') return null;
  const parts = range.trim().toUpperCase().split(':');
  if (parts.length < 1 || parts.length > 2) return null;
  const start = parseCoord(parts[0]);
  const end = parseCoord(parts.length === 2 ? parts[1] : parts[0]);
  if (!start || !end) return null;
  return {
    startRow: Math.min(start.row, end.row),
    endRow: Math.max(start.row, end.row),
    startCol: Math.min(start.col, end.col),
    endCol: Math.max(start.col, end.col),
  };
}

function rangeString(rc) {
  return store.columnName(rc.startCol) + rc.startRow + ':' + store.columnName(rc.endCol) + rc.endRow;
}

function adjustFormula(formula, dRow, dCol) {
  if (typeof formula !== 'string' || !formula.startsWith('=')) return formula;
  let invalid = false;
  const text = formula.replace(/\$?[A-Za-z]{1,3}\$?[1-9][0-9]*/g, (ref) => {
    const m = /^(\$?)([A-Za-z]{1,3})(\$?)([1-9][0-9]*)$/.exec(ref);
    if (!m) return ref;
    const colAbs = m[1] === '$';
    const rowAbs = m[3] === '$';
    let col = 0;
    for (let i = 0; i < m[2].length; i++) {
      col = col * 26 + (m[2].charCodeAt(i) - 64);
    }
    const row = parseInt(m[4], 10);
    let newCol = colAbs ? col : col + dCol;
    let newRow = rowAbs ? row : row + dRow;
    if (newCol < 1 || newRow < 1) {
      invalid = true;
      return '#REF!';
    }
    return (colAbs ? '$' : '') + store.columnName(newCol) + (rowAbs ? '$' : '') + newRow;
  });
  return invalid ? '=#REF!' : text;
}

async function handle(req, res, ctx) {
  const m = ctx.match('POST', '/api/workbooks/:id/sheets/:sheetId/range/transfer');
  if (!m) return false;

  const body = (await ctx.readBody(req)) || {};

  const workbook = store.getWorkbook(m.id);
  if (!workbook) {
    return ctx.sendJson(res, 404, { error: 'Workbook not found' });
  }

  const sheet = (workbook.sheets || []).find((s) => s.id === m.sheetId);
  if (!sheet) {
    return ctx.sendJson(res, 404, { error: 'Worksheet not found' });
  }

  let source = body.source;
  if (source && typeof source === 'object') {
    const start = source.start || source.startCell;
    const end = source.end || source.endCell || start;
    source = start + ':' + end;
  }
  if (typeof source !== 'string' || !source.trim()) {
    return ctx.sendJson(res, 400, { error: 'Source range is required' });
  }
  if (typeof body.target !== 'string' || !body.target.trim()) {
    return ctx.sendJson(res, 400, { error: 'Target cell is required' });
  }

  const src = parseRange(source);
  const targetCoord = parseCoord(body.target);
  if (!src) {
    return ctx.sendJson(res, 400, { error: 'Invalid source range' });
  }
  if (!targetCoord) {
    return ctx.sendJson(res, 400, { error: 'Invalid target cell' });
  }

  const rowLimit = sheet.rowCount || 30;
  const colLimit = sheet.colCount || 26;
  if (
    src.startRow < 1 ||
    src.endRow > rowLimit ||
    src.startCol < 1 ||
    src.endCol > colLimit
  ) {
    return ctx.sendJson(res, 400, { error: 'Source range is outside the worksheet' });
  }

  const dRow = targetCoord.row - src.startRow;
  const dCol = targetCoord.col - src.startCol;
  const height = src.endRow - src.startRow + 1;
  const width = src.endCol - src.startCol + 1;
  const targetEndRow = targetCoord.row + height - 1;
  const targetEndCol = targetCoord.col + width - 1;

  if (targetEndRow > rowLimit || targetEndCol > colLimit || targetCoord.row < 1 || targetCoord.col < 1) {
    return ctx.sendJson(res, 400, { error: 'Target range is outside the worksheet' });
  }

  const updates = [];
  for (let r = src.startRow; r <= src.endRow; r++) {
    for (let c = src.startCol; c <= src.endCol; c++) {
      const sourceCoord = store.columnName(c) + r;
      const targetCoordStr = store.columnName(c + dCol) + (r + dRow);
      const cell = (sheet.cells || {})[sourceCoord];
      if (!cell || (cell.v === undefined && cell.f === undefined)) {
        updates.push({ coord: targetCoordStr, cell: null });
      } else if (cell.f !== undefined) {
        updates.push({
          coord: targetCoordStr,
          cell: { f: adjustFormula(cell.f, dRow, dCol), v: 0 },
        });
      } else {
        updates.push({ coord: targetCoordStr, cell: { v: cell.v } });
      }
    }
  }

  for (const update of updates) {
    if (update.cell && update.cell.f === undefined) {
      const error = validations.checkValue(sheet, update.coord, update.cell.v);
      if (error) {
        return ctx.sendJson(res, 400, { error });
      }
    }
  }

  history.push(workbook);

  const targetCells = new Set();
  for (let r = 0; r < height; r++) {
    for (let c = 0; c < width; c++) {
      targetCells.add(store.columnName(targetCoord.col + c) + (targetCoord.row + r));
    }
  }

  for (const update of updates) {
    if (update.cell === null) {
      delete sheet.cells[update.coord];
    } else {
      sheet.cells[update.coord] = update.cell;
    }
  }

  if (body.cut) {
    for (let r = src.startRow; r <= src.endRow; r++) {
      for (let c = src.startCol; c <= src.endCol; c++) {
        const sourceCoord = store.columnName(c) + r;
        if (!targetCells.has(sourceCoord)) {
          delete sheet.cells[sourceCoord];
        }
      }
    }

    const srcRange = rangeString(src);
    const targetRange = rangeString({
      startRow: targetCoord.row,
      endRow: targetEndRow,
      startCol: targetCoord.col,
      endCol: targetEndCol,
    });

    if (Array.isArray(sheet.validations)) {
      for (const validation of sheet.validations) {
        if (validation.range === srcRange) {
          validation.range = targetRange;
        }
      }
    }
  }

  formulas.recalcSheet(sheet);
  workbook.updatedAt = new Date().toISOString();
  store.save();

  return ctx.sendJson(res, 200, { workbook });
}

module.exports = { handle };

