'use strict';

function columnLettersToNumber(letters) {
  let n = 0;
  for (let i = 0; i < letters.length; i++) {
    n = n * 26 + (letters.charCodeAt(i) - 64);
  }
  return n;
}

function parseCoord(coord) {
  const m = /^([A-Z]+)([1-9][0-9]*)$/.exec(String(coord).toUpperCase());
  if (!m) return null;
  return {
    col: columnLettersToNumber(m[1]),
    row: parseInt(m[2], 10),
  };
}

function rangeContains(range, coord) {
  const parts = String(range).toUpperCase().split(':');
  if (parts.length !== 2) {
    return parts[0] === String(coord).toUpperCase();
  }
  const start = parseCoord(parts[0]);
  const end = parseCoord(parts[1]);
  const target = parseCoord(coord);
  if (!start || !end || !target) return false;
  const minRow = Math.min(start.row, end.row);
  const maxRow = Math.max(start.row, end.row);
  const minCol = Math.min(start.col, end.col);
  const maxCol = Math.max(start.col, end.col);
  return target.row >= minRow && target.row <= maxRow && target.col >= minCol && target.col <= maxCol;
}

function dropdownMessage(rule) {
  const options = Array.isArray(rule.options) ? rule.options.map((o) => String(o)) : [];
  return 'Please select one of the following values: ' + options.join(',');
}

function numberMessage(rule) {
  if (rule.min !== undefined && rule.max !== undefined) {
    if (Number(rule.min) === 0 && Number(rule.max) === 100) {
      return `Please enter a number from ${rule.min} to ${rule.max}`;
    }
    return `Please enter a number between ${rule.min} and ${rule.max}`;
  }
  if (rule.min !== undefined) {
    return `Please enter a number greater than or equal to ${rule.min}`;
  }
  if (rule.max !== undefined) {
    return `Please enter a number less than or equal to ${rule.max}`;
  }
  return 'Please enter a valid number';
}

function checkValue(sheet, coord, value) {
  const rules = Array.isArray(sheet.validations) ? sheet.validations : [];
  const rule = rules.find((r) => rangeContains(r.range, coord));
  if (!rule) return null;

  if (rule.type === 'number') {
    let num = typeof value === 'number' ? value : null;
    if (num === null && typeof value === 'string' && value.trim() !== '') {
      const n = Number(value);
      if (Number.isFinite(n)) num = n;
    }
    if (num === null) return numberMessage(rule);
    if (rule.min !== undefined && num < rule.min) return numberMessage(rule);
    if (rule.max !== undefined && num > rule.max) return numberMessage(rule);
  }

  if (rule.type === 'dropdown') {
    const options = Array.isArray(rule.options) ? rule.options.map((o) => String(o)) : [];
    const s = String(value);
    if (!options.includes(s)) {
      return dropdownMessage(rule);
    }
  }

  return null;
}

module.exports = { checkValue, rangeContains, parseCoord };

