'use strict';

const store = require('./store');
const history = require('./history');

function parseCSV(text) {
  if (typeof text !== 'string') return null;
  text = text.replace(/^\uFEFF/, '');

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
      continue;
    }

    if (ch === '"') {
      if (field.length > 0) return null;
      inQuotes = true;
    } else if (ch === ',') {
      row.push(field);
      field = '';
    } else if (ch === '\r') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      if (text[i + 1] === '\n') i++;
    } else if (ch === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
    } else {
      field += ch;
    }
  }

  if (inQuotes) return null;

  row.push(field);
  if (!(rows.length > 0 && row.length === 1 && row[0] === '')) {
    rows.push(row);
  }

  return rows;
}

function csvField(value) {
  const s = value === null || value === undefined ? '' : String(value);
  if (/[",\n\r]/.test(s)) {
    return '"' + s.replace(/"/g, '""') + '"';
  }
  return s;
}

function normalizeSelectionValue(value) {
  if (typeof value === 'string') {
    const coord = value.toUpperCase();
    if (!/^([A-Z]+)([1-9][0-9]*)$/.test(coord)) return null;
    return { start: coord, end: coord };
  }
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    const start = value.start ? String(value.start).toUpperCase() : null;
    const end = value.end ? String(value.end).toUpperCase() : null;
    if (!start || !end) return null;
    if (!/^([A-Z]+)([1-9][0-9]*)$/.test(start) || !/^([A-Z]+)([1-9][0-9]*)$/.test(end)) return null;
    return { start, end };
  }
  return null;
}

function coordInBounds(sheet, coord) {
  const m = /^([A-Z]+)([1-9][0-9]*)$/.exec(coord);
  if (!m) return false;
  let col = 0;
  for (let i = 0; i < m[1].length; i++) col = col * 26 + (m[1].charCodeAt(i) - 64);
  const row = parseInt(m[2], 10);
  return row >= 1 && row <= (sheet.rowCount || 30) && col >= 1 && col <= (sheet.colCount || 26);
}

function columnLettersToNumber(letters) {
  let n = 0;
  for (let i = 0; i < letters.length; i++) {
    n = n * 26 + (letters.charCodeAt(i) - 64);
  }
  return n;
}

function sheetToCSV(sheet) {
  const cells = sheet.cells || {};
  let maxRow = 1;
  let maxCol = 1;

  for (const coord of Object.keys(cells)) {
    const match = /^([A-Z]+)([1-9][0-9]*)$/.exec(coord);
    if (!match) continue;
    const cell = cells[coord];
    if (!cell || cell.v === undefined || cell.v === '') continue;
    const row = parseInt(match[2], 10);
    const col = columnLettersToNumber(match[1]);
    if (row > maxRow) maxRow = row;
    if (col > maxCol) maxCol = col;
  }

  const rowLimit = sheet.rowCount || 1;
  const colLimit = sheet.colCount || 1;
  if (maxRow > rowLimit) maxRow = rowLimit;
  if (maxCol > colLimit) maxCol = colLimit;

  const lines = [];
  for (let r = 1; r <= maxRow; r++) {
    const row = [];
    for (let c = 1; c <= maxCol; c++) {
      const coord = store.columnName(c) + r;
      const cell = cells[coord];
      row.push(cell && cell.v !== undefined ? cell.v : '');
    }
    lines.push(row.map(csvField).join(','));
  }
  return lines.join('\n');
}

async function handle(req, res, ctx) {
  let m;

  if ((m = ctx.match('GET', '/api/workbooks'))) {
    return ctx.sendJson(res, 200, { workbooks: store.listWorkbooks() });
  }

  if ((m = ctx.match('POST', '/api/workbooks/import'))) {
    const body = (await ctx.readBody(req)) || {};
    if (typeof body.csv !== 'string') {
      return ctx.sendJson(res, 400, { error: 'CSV content is required' });
    }
    const rows = parseCSV(body.csv);
    if (!rows) {
      return ctx.sendJson(res, 400, { error: 'Invalid CSV file format. Import failed.' });
    }
    const name =
      typeof body.name === 'string' && body.name.trim()
        ? body.name.trim()
        : 'Imported workbook';
    const workbook = store.createWorkbookFromCSV(name, rows);
    return ctx.sendJson(res, 201, { workbook });
  }

  if ((m = ctx.match('POST', '/api/workbooks'))) {
    const body = (await ctx.readBody(req)) || {};
    const name =
      typeof body.name === 'string' && body.name.trim()
        ? body.name.trim()
        : 'Untitled spreadsheet';
    const workbook = store.createWorkbook(name);
    return ctx.sendJson(res, 201, { workbook });
  }

  if ((m = ctx.match('GET', '/api/workbooks/:id/export.csv'))) {
    const workbook = store.getWorkbook(m.id);
    if (!workbook) {
      return ctx.sendJson(res, 404, { error: 'Workbook not found' });
    }
    const sheetId = (ctx.query && ctx.query.get('sheetId')) || workbook.activeSheetId;
    const sheet = (Array.isArray(workbook.sheets) ? workbook.sheets : []).find(
      (s) => s.id === sheetId
    );
    if (!sheet) {
      return ctx.sendJson(res, 404, { error: 'Worksheet not found' });
    }
    res.statusCode = 200;
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', 'attachment; filename="export.csv"');
    res.end(sheetToCSV(sheet));
    return true;
  }

  if ((m = ctx.match('GET', '/api/workbooks/:id'))) {
    const workbook = store.getWorkbook(m.id);
    if (!workbook) {
      return ctx.sendJson(res, 404, { error: 'Workbook not found' });
    }
    return ctx.sendJson(res, 200, { workbook });
  }

  if ((m = ctx.match('PATCH', '/api/workbooks/:id'))) {
    const body = (await ctx.readBody(req)) || {};
    const workbook = store.getWorkbook(m.id);
    if (!workbook) {
      return ctx.sendJson(res, 404, { error: 'Workbook not found' });
    }

    if (body.name !== undefined) {
      if (typeof body.name !== 'string' || !body.name.trim()) {
        return ctx.sendJson(res, 400, { error: 'Workbook name cannot be empty' });
      }
      history.push(workbook);
      workbook.name = body.name.trim();
    }

    if (body.activeSheetId !== undefined) {
      const sheetExists = (workbook.sheets || []).some((s) => s.id === body.activeSheetId);
      if (!sheetExists) {
        return ctx.sendJson(res, 400, { error: 'Worksheet not found' });
      }
      workbook.activeSheetId = body.activeSheetId;
    }

    if (body.selectedCells !== undefined) {
      if (typeof body.selectedCells !== 'object' || body.selectedCells === null || Array.isArray(body.selectedCells)) {
        return ctx.sendJson(res, 400, { error: 'selectedCells must be an object' });
      }
      for (const sheetId of Object.keys(body.selectedCells)) {
        const sheet = (workbook.sheets || []).find((s) => s.id === sheetId);
        if (!sheet) {
          return ctx.sendJson(res, 400, { error: 'Worksheet not found' });
        }
        const cell = body.selectedCells[sheetId];
        if (typeof cell !== 'string' || !/^([A-Z]+)([1-9][0-9]*)$/.test(cell.toUpperCase())) {
          return ctx.sendJson(res, 400, { error: 'Invalid cell coordinate' });
        }
        const coordMatch = /^([A-Z]+)([1-9][0-9]*)$/.exec(cell.toUpperCase());
        const col = columnLettersToNumber(coordMatch[1]);
        const row = parseInt(coordMatch[2], 10);
        if (row > (sheet.rowCount || 30) || col > (sheet.colCount || 26)) {
          return ctx.sendJson(res, 400, { error: 'Cell is outside the worksheet' });
        }
        sheet.selectedCell = cell.toUpperCase();
        sheet.selection = { start: cell.toUpperCase(), end: cell.toUpperCase() };
      }
    }

    if (body.selections !== undefined) {
      if (typeof body.selections !== 'object' || body.selections === null || Array.isArray(body.selections)) {
        return ctx.sendJson(res, 400, { error: 'selections must be an object' });
      }
      for (const sheetId of Object.keys(body.selections)) {
        const sheet = (workbook.sheets || []).find((s) => s.id === sheetId);
        if (!sheet) {
          return ctx.sendJson(res, 400, { error: 'Worksheet not found' });
        }
        const parsed = normalizeSelectionValue(body.selections[sheetId]);
        if (!parsed) {
          return ctx.sendJson(res, 400, { error: 'Invalid cell selection' });
        }
        if (!coordInBounds(sheet, parsed.start) || !coordInBounds(sheet, parsed.end)) {
          return ctx.sendJson(res, 400, { error: 'Selection is outside the worksheet' });
        }
        sheet.selection = parsed;
        sheet.selectedCell = parsed.start;
      }
    }

    if (body.name === undefined && body.activeSheetId === undefined && body.selectedCells === undefined && body.selections === undefined) {
      return ctx.sendJson(res, 400, { error: 'Nothing to update' });
    }

    if (body.name !== undefined || body.activeSheetId !== undefined) {
      workbook.updatedAt = new Date().toISOString();
    }
    store.save();
    return ctx.sendJson(res, 200, { workbook });
  }

  return false;
}

module.exports = { handle };

