import { test, expect } from '@playwright/test';
import * as h from './evogit-helpers';

async function setCell(page: import('@playwright/test').Page, cell: string, value: string) {
  await h.cell(page, cell).click();
  await h.fill(page, 'Formula bar', value);
  await page.keyboard.press('Enter');
}

async function readDownload(download: import('@playwright/test').Download) {
  let content = '';
  const stream = await download.createReadStream();
  stream.setEncoding('utf8');
  stream.on('data', chunk => (content += chunk));
  await new Promise(resolve => stream.on('end', resolve));
  return content;
}

