import { test, expect } from '@playwright/test';
import * as h from './evogit-helpers';

async function setCellValue(page: any, coord: string, value: string) {
  const cell = page.getByRole('gridcell', { name: h.exact(coord) });
  await cell.dblclick();
  const editor = page.getByRole('textbox', { name: h.exact(`Edit ${coord}`) });
  await editor.fill(value);
  await page.keyboard.press('Enter');
}

async function setClipboard(page: any, text: string) {
  await page.evaluate((txt) => navigator.clipboard.writeText(txt), text);
}

async function setNumericValidation(page: any, range: string, min: string, max: string) {
  await h.click(page, 'Data');
  await page.getByRole('menuitem', { name: h.exact('Data validation') }).click();
  const dialog = h.region(page, 'dialog', 'Data validation');
  await h.fill(dialog, 'Range', range);
  await h.select(dialog, 'Type', 'Number');
  await h.fill(dialog, 'Min', min);
  await h.fill(dialog, 'Max', max);
  await h.click(dialog, 'Save');
}

