import { test, expect } from '@playwright/test';
import * as h from './evogit-helpers';

// Helper: set a cell value via the Formula bar (REQ-3-1-1)
async function setCellValue(page: any, cell: string, value: string) {
  const cellLocator = h.cell(page, cell);
  await cellLocator.click();
  const formulaBar = page.getByLabel(h.exact('Formula bar'));
  await formulaBar.fill(value);
  await formulaBar.press('Enter');
}

// Helper: get trimmed text content of a grid cell
async function cellText(page: any, cell: string): Promise<string> {
  return (await h.cell(page, cell).innerText()).trim();
}

test('REQ-4-2-2 #1: Division by zero error #DIV/0! persists and can be fixed', async ({ page }) => {
  await page.goto('/');
  await h.click(page, 'Q3 Sales');
  // Overwrite seed A1/B1 (seed conflict) and enter the required base formulas
  await setCellValue(page, 'A1', '2');
  await setCellValue(page, 'B1', '3');
  await setCellValue(page, 'C1', '=A1+B1');
  await setCellValue(page, 'D1', '=C1*2');
  // Force a division by zero error in C1
  await setCellValue(page, 'C1', '=A1/0');
  expect(await cellText(page, 'C1')).toBe('#DIV/0!');
  expect(await cellText(page, 'D1')).toBe('#DIV/0!'); // dependent recalculates
  await h.cell(page, 'C1').click();
  await expect(page.getByLabel(h.exact('Formula bar'))).toHaveValue('=A1/0');
  // Error does not block other cells
  expect(await cellText(page, 'B1')).toBe('3');
  await page.reload();
  expect(await cellText(page, 'C1')).toBe('#DIV/0!');
  expect(await cellText(page, 'D1')).toBe('#DIV/0!');
  await h.cell(page, 'C1').click();
  await expect(page.getByLabel(h.exact('Formula bar'))).toHaveValue('=A1/0');
  // Fix the error
  await setCellValue(page, 'C1', '=A1+B1');
  expect(await cellText(page, 'C1')).toBe('5');
  expect(await cellText(page, 'D1')).toBe('10');
  await h.cell(page, 'C1').click();
  await expect(page.getByLabel(h.exact('Formula bar'))).toHaveValue('=A1+B1');
  await page.reload();
  expect(await cellText(page, 'C1')).toBe('5');
  expect(await cellText(page, 'D1')).toBe('10');
  await h.cell(page, 'C1').click();
  await expect(page.getByLabel(h.exact('Formula bar'))).toHaveValue('=A1+B1');
});

