  await h.cell(page, end).click({ modifiers: ['Shift'] });
}

// Helper: open the "Sort range" dialog from the Data menu
async function openSortDialog(page: import('@playwright/test').Page) {
  await h.click(page, 'Data');
  await h.click(page, 'Sort range');
  const dialog = page.getByRole('dialog', { name: h.exact('Sort range') });
  await expect(dialog).toBeVisible();
}

// Helper: set the sort column and order, optionally toggle header row
async function configureSort(page: import('@playwright/test').Page, by: string, order: string, header: boolean) {
  await h.select(page, 'Sort by', by);
  await h.select(page, 'Order', order);
  const headerCheckbox = page.getByRole('checkbox', { name: h.exact('Data has header row') });
  const isChecked = await headerCheckbox.isChecked();
  if (header !== isChecked) {
    await headerCheckbox.click();
  }
}

// Helper: assert the visible grid cell values after sorting
async function expectGridRows(page: import('@playwright/test').Page, rows: Array<[string, string, string]>) {
  for (let i = 0; i < rows.length; i++) {
    const colA = h.cell(page, `A${i + 1}`);
    const colB = h.cell(page, `B${i + 1}`);
    const colC = h.cell(page, `C${i + 1}`);
    await expect(colA).toHaveText(rows[i][0]);
    await expect(colB).toHaveText(rows[i][1]);
    await expect(colC).toHaveText(rows[i][2]);
  }
}

