// ---------------------------------------------------------------------------
// Helper: select a contiguous range using Shift+Click
// ---------------------------------------------------------------------------
async function selectRange(page: import('@playwright/test').Page, from: string, to: string) {
  await page.getByRole('gridcell', { name: h.exact(from) }).click();
  await page.keyboard.down('Shift');
  await page.getByRole('gridcell', { name: h.exact(to) }).click();
  await page.keyboard.up('Shift');
}

// ---------------------------------------------------------------------------
// Open workbook Q3 Sales and wait for grid
// ---------------------------------------------------------------------------
async function openWorkbook(page: import('@playwright/test').Page) {
  await page.goto('/');
  await page.getByRole('link', { name: h.exact('Q3 Sales') }).click();
  await expect(page.getByRole('grid', { name: h.exact('Worksheet grid') })).toBeVisible();
}

// ---------------------------------------------------------------------------
// Open the Data validation dialog for the selected range
// ---------------------------------------------------------------------------
async function openDataValidation(page: import('@playwright/test').Page) {
  await page.getByRole('button', { name: h.exact('Data') }).click();
  await page.getByRole('menuitem', { name: h.exact('Data validation') }).click();
  await expect(page.getByRole('dialog', { name: h.exact('Data validation') })).toBeVisible();
}

// ---------------------------------------------------------------------------
// Set a numeric rule (min/max) and save
// ---------------------------------------------------------------------------
async function setNumericRule(page: import('@playwright/test').Page, min: string, max: string) {
  await page.getByRole('combobox', { name: h.exact('Rule type') }).selectOption({ label: 'Number range' });
  await page.getByLabel('Minimum').fill(min);
  await page.getByLabel('Maximum').fill(max);
  await page.getByRole('button', { name: h.exact('Save') }).click();
  await expect(page.getByRole('dialog', { name: h.exact('Data validation') })).not.toBeVisible();
}

// ---------------------------------------------------------------------------
// Set a dropdown rule with allowed values (comma separated) and save
// ---------------------------------------------------------------------------
async function setDropdownRule(page: import('@playwright/test').Page, allowedValues: string) {
  await page.getByRole('combobox', { name: h.exact('Rule type') }).selectOption({ label: 'Dropdown' });
  await page.getByLabel('Allowed values').fill(allowedValues);
  await page.getByRole('button', { name: h.exact('Save') }).click();
  await expect(page.getByRole('dialog', { name: h.exact('Data validation') })).not.toBeVisible();
}

// ---------------------------------------------------------------------------
// Fill a cell via double-click inline editor (grid path)
// ---------------------------------------------------------------------------
async function fillCell(page: import('@playwright/test').Page, cell: string, value: string) {
  await page.getByRole('gridcell', { name: h.exact(cell) }).dblclick();
  const editor = page.getByLabel(`Edit ${cell}`);
  await editor.fill(value);
  await page.keyboard.press('Enter');
}

// ---------------------------------------------------------------------------
// Fill a cell via the formula bar
// ---------------------------------------------------------------------------
async function fillCellViaFormulaBar(page: import('@playwright/test').Page, cell: string, value: string) {
  await page.getByRole('gridcell', { name: h.exact(cell) }).click();
  await page.getByLabel('Formula bar').fill(value);
  await page.keyboard.press('Enter');
}

