import { test, expect } from '@playwright/test';
import * as h from './evogit-helpers';

// Helper to open the seeded workbook and select the range A1:C6
async function openWorkbookAndSelectRange(page: any) {
  await page.goto('/');
  await h.click(page, 'Q3 Sales');
  // Select the source range A1:C6
  await page.getByRole('gridcell', { name: h.exact('A1') }).click();
  await page.getByRole('gridcell', { name: h.exact('C6') }).click({ modifiers: ['Shift'] });
}

// Helper to create the pivot worksheet and open the pivot editor
async function createPivot(page: any) {
  // Open Data menu and click Create pivot table
  await page.getByRole('button', { name: h.exact('Data') }).click();
  await page.getByRole('menuitem', { name: h.exact('Create pivot table') }).click();
  const dialog = h.region(page, 'dialog', 'Create pivot table');
  await h.expectText(dialog, 'Source range: A1:C6');
  await page.getByRole('radio', { name: h.exact('New worksheet') }).check();
  await page.getByRole('button', { name: h.exact('Create') }).click();
  // Wait for the Pivot1 tab and switch to it
  const pivotTab = page.getByRole('tab', { name: h.exact('Pivot1') });
  await expect(pivotTab).toBeVisible();
  await pivotTab.click();
}

