import { normalizeSelection, parseCoord } from './rangeUtils';

function columnName(n: number): string {
  let name = '';
  let value = n;
  while (value > 0) {
    const rem = (value - 1) % 26;
    name = String.fromCharCode(65 + rem) + name;
    value = Math.floor((value - 1) / 26);
  }
  return name;
}

export interface FilterCriteria {
  values?: string[];
  condition?: string;
  value?: string | number;
}

export interface FilterState {
  range?: string;
  criteria?: Record<string, FilterCriteria>;
}

function parseRangeString(range: string) {
  const parts = String(range).trim().toUpperCase().split(':');
  if (parts.length < 1 || parts.length > 2) return null;
  const start = parseCoord(parts[0]);
  const end = parseCoord(parts.length === 2 ? parts[1] : parts[0]);
  if (!start || !end) return null;
  return {
    startRow: Math.min(start.row, end.row),
    endRow: Math.max(start.row, end.row),
    startCol: Math.min(start.col, end.col),
    endCol: Math.max(start.col, end.col),
  };
}

export function usedRangeForSheet(sheet: any): string {
  let minRow = 1;
  let minCol = 1;
  let maxRow = 1;
  let maxCol = 1;
  const cells = sheet && sheet.cells ? sheet.cells : {};
  for (const coord of Object.keys(cells)) {
    const rc = parseCoord(coord);
    if (!rc) continue;
    if (rc.row < minRow) minRow = rc.row;
    if (rc.row > maxRow) maxRow = rc.row;
    if (rc.col < minCol) minCol = rc.col;
    if (rc.col > maxCol) maxCol = rc.col;
  }
  return columnName(minCol) + minRow + ':' + columnName(maxCol) + maxRow;
}

export function getFilterRangeForSheet(sheet: any, start?: string, end?: string): string {
  if (start && end && start !== end) {
    const normalized = normalizeSelection(start, end);
    return normalized.start + ':' + normalized.end;
  }
  return usedRangeForSheet(sheet);
}

export function getHeaderForColumn(sheet: any, range: string, colNumber: number): string | null {
  const rc = parseRangeString(range);
  if (!rc) return null;
  if (colNumber < rc.startCol || colNumber > rc.endCol) return null;
  const cell = sheet && sheet.cells ? sheet.cells[columnName(colNumber) + rc.startRow] : undefined;
  const value = cell && cell.v !== undefined ? cell.v : '';
  if (value === '' || value === null || value === undefined) return null;
  return String(value);
}

export function distinctValuesForColumn(sheet: any, range: string, header: string): string[] {
  const rc = parseRangeString(range);
  if (!rc) return [];
  const headers: string[] = [];
  for (let c = rc.startCol; c <= rc.endCol; c++) {
    const cell = sheet && sheet.cells ? sheet.cells[columnName(c) + rc.startRow] : undefined;
    headers.push(cell && cell.v !== undefined ? String(cell.v) : '');
  }
  const idx = headers.indexOf(header);
  if (idx === -1) return [];
  const col = rc.startCol + idx;
  const out: string[] = [];
  const seen = new Set<string>();
  for (let r = rc.startRow + 1; r <= rc.endRow; r++) {
    const cell = sheet && sheet.cells ? sheet.cells[columnName(col) + r] : undefined;
    const value = cell && cell.v !== undefined ? cell.v : '';
    if (value === '' || value === null || value === undefined) continue;
    const key = String(value);
    if (!seen.has(key)) {
      seen.add(key);
      out.push(key);
    }
  }
  return out;
}

function isEmptyValue(value: unknown): boolean {
  return value === undefined || value === null || value === '' || (typeof value === 'string' && value.trim() === '');
}

function parseDateValue(value: unknown): number | null {
  const s = String(value).trim();
  const iso = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/.exec(s);
  if (iso) {
    const d = Date.UTC(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
    return Number.isNaN(d) ? null : d;
  }
  const us = /^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/.exec(s);
  if (us) {
    const d = Date.UTC(Number(us[3]), Number(us[1]) - 1, Number(us[2]));
    return Number.isNaN(d) ? null : d;
  }
  const d = Date.parse(s);
  return Number.isNaN(d) ? null : d;
}

export function rowMatchesFilter(sheet: any, row: number, filter: FilterState | null | undefined): boolean {
  if (!filter || !filter.range) return true;
  const rc = parseRangeString(filter.range);
  if (!rc) return true;
  if (row < rc.startRow || row > rc.endRow) return true;
  if (row === rc.startRow) return true;

  const criteria = filter.criteria || {};
  const headers: string[] = [];
  for (let c = rc.startCol; c <= rc.endCol; c++) {
    const cell = sheet && sheet.cells ? sheet.cells[columnName(c) + rc.startRow] : undefined;
    headers.push(cell && cell.v !== undefined ? String(cell.v) : '');
  }

  for (const header of Object.keys(criteria)) {
    const idx = headers.indexOf(header);
    if (idx === -1) continue;
    const col = rc.startCol + idx;
    const cell = sheet && sheet.cells ? sheet.cells[columnName(col) + row] : undefined;
    const value = cell && cell.v !== undefined ? cell.v : '';
    const rule = criteria[header];
    if (!rule) continue;

    if (Array.isArray(rule.values)) {
      if (rule.values.length === 0) return false;
      if (isEmptyValue(value)) return false;
      if (!rule.values.includes(String(value))) return false;
      continue;
    }

    const condition = rule.condition;
    if (!condition) continue;

    if (condition === 'Is empty') {
      if (isEmptyValue(value)) continue;
      return false;
    }
    if (condition === 'Is not empty') {
      if (!isEmptyValue(value)) continue;
      return false;
    }
    if (condition === 'Text contains') {
      const needle = String(rule.value ?? '').toLowerCase();
      if (String(value).toLowerCase().includes(needle)) continue;
      return false;
    }
    if (condition === 'Greater than') {
      const n = Number(value);
      const m = Number(rule.value);
      if (Number.isFinite(n) && Number.isFinite(m) && n > m) continue;
      return false;
    }
    if (condition === 'Before') {
      const d1 = parseDateValue(value);
      const d2 = parseDateValue(rule.value);
      if (d1 !== null && d2 !== null) {
        if (d1 < d2) continue;
        return false;
      }
      if (String(value) < String(rule.value)) continue;
      return false;
    }
    return false;
  }

  return true;
}

