export interface FormulaCell {
  v?: string | number | boolean;
  f?: string;
  _invalidRef?: boolean;
}

export interface FormulaSheet {
  id: string;
  rowCount: number;
  colCount: number;
  cells: Record<string, FormulaCell>;
  [key: string]: unknown;
}

type Token =
  | { type: 'num'; value: number }
  | { type: 'cell'; value: string }
  | { type: 'func'; value: string }
  | { type: 'op'; value: string }
  | { type: 'lparen' }
  | { type: 'rparen' }
  | { type: 'comma' }
  | { type: 'colon' }
  | { type: 'eof' };

function formulaError(message: string): Error {
  const err = new Error(message) as Error & { formulaError?: boolean };
  err.formulaError = true;
  return err;
}

const ERROR_VALUES = /^#(DIV\/0!|REF!|NAME\?|ERROR!|VALUE!)$/;

function isErrorValue(value: unknown): value is string {
  return typeof value === 'string' && ERROR_VALUES.test(value);
}

function columnLettersToNumber(letters: string): number {
  let n = 0;
  for (let i = 0; i < letters.length; i++) {
    n = n * 26 + (letters.charCodeAt(i) - 64);
  }
  return n;
}

export function columnName(n: number): string {
  let name = '';
  let value = n;
  while (value > 0) {
    const rem = (value - 1) % 26;
    name = String.fromCharCode(65 + rem) + name;
    value = Math.floor((value - 1) / 26);
  }
  return name;
}

function isCellRef(word: string): boolean {
  return /^\$?[A-Za-z]{1,3}\$?[1-9][0-9]*$/.test(word);
}

function cellRC(coord: string): { row: number; col: number } | null {
  const m = /^\$?([A-Za-z]+)\$?([1-9][0-9]*)$/.exec(coord);
  if (!m) return null;
  return { row: parseInt(m[2], 10), col: columnLettersToNumber(m[1].toUpperCase()) };
}

function cellValue(sheet: FormulaSheet, coord: string): unknown {
  const rc = cellRC(coord);
  if (!rc) throw formulaError('#VALUE!');
  if (rc.row < 1 || rc.row > (sheet.rowCount || 0) || rc.col < 1 || rc.col > (sheet.colCount || 0)) {
    throw formulaError('#REF!');
  }
  const cell = (sheet.cells || {})[columnName(rc.col) + rc.row];
  if (!cell || cell.v === undefined) return 0;
  return cell.v;
}

function toNumber(value: unknown): number {
  if (isErrorValue(value)) throw formulaError(value);
  if (typeof value === 'number') return value;
  if (typeof value === 'boolean') return value ? 1 : 0;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed === '') return 0;
    const n = Number(trimmed);
    if (Number.isFinite(n)) return n;
  }
  throw formulaError('#VALUE!');
}

function tokenize(expr: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < expr.length) {
    const ch = expr[i];
    if (ch === ' ' || ch === '\t') {
      i++;
      continue;
    }
    if (/[0-9.]/.test(ch)) {
      let num = '';
      while (i < expr.length && /[0-9.]/.test(expr[i])) {
        num += expr[i];
        i++;
      }
      const n = Number(num);
      if (Number.isNaN(n)) throw formulaError('#VALUE!');
      tokens.push({ type: 'num', value: n });
      continue;
    }
    if (ch === '$' || /[A-Za-z]/.test(ch)) {
      let word = ch;
      i++;
      while (i < expr.length && (/[A-Za-z0-9]/.test(expr[i]) || expr[i] === '$')) {
        word += expr[i];
        i++;
      }
      if (isCellRef(word)) tokens.push({ type: 'cell', value: word.toUpperCase() });
      else tokens.push({ type: 'func', value: word.toUpperCase() });
      continue;
    }
    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '^' || ch === '%') {
      tokens.push({ type: 'op', value: ch });
      i++;
      continue;
    }
    if (ch === '(') {
      tokens.push({ type: 'lparen' });
      i++;
      continue;
    }
    if (ch === ')') {
      tokens.push({ type: 'rparen' });
      i++;
      continue;
    }
    if (ch === ',') {
      tokens.push({ type: 'comma' });
      i++;
      continue;
    }
    if (ch === ':') {
      tokens.push({ type: 'colon' });
      i++;
      continue;
    }
    throw formulaError('#ERROR!');
  }
  tokens.push({ type: 'eof' });
  return tokens;
}

function readRangeValues(sheet: FormulaSheet, startCoord: string, endCoord: string): unknown[] {
  const start = cellRC(startCoord);
  const end = cellRC(endCoord);
  if (!start || !end) throw formulaError('#VALUE!');
  const minRow = Math.min(start.row, end.row);
  const maxRow = Math.max(start.row, end.row);
  const minCol = Math.min(start.col, end.col);
  const maxCol = Math.max(start.col, end.col);
  if (minRow < 1 || maxRow > (sheet.rowCount || 0) || minCol < 1 || maxCol > (sheet.colCount || 0)) {
    throw formulaError('#REF!');
  }
  const values: unknown[] = [];
  for (let r = minRow; r <= maxRow; r++) {
    for (let c = minCol; c <= maxCol; c++) {
      const coord = columnName(c) + r;
      const cell = (sheet.cells || {})[coord];
      values.push(cell && cell.v !== undefined ? cell.v : null);
    }
  }
  return values;
}

function numericValues(args: unknown[]): number[] {
  const values: number[] = [];
  const visit = (arg: unknown) => {
    if (Array.isArray(arg)) {
      (arg as unknown[]).forEach(visit);
    } else if (arg === null || arg === undefined) {
      return;
    } else if (typeof arg === 'number' && Number.isFinite(arg)) {
      values.push(arg);
    } else if (typeof arg === 'string') {
      const trimmed = arg.trim();
      if (trimmed !== '' && Number.isFinite(Number(trimmed))) values.push(Number(trimmed));
    }
  };
  args.forEach(visit);
  return values;
}

function callFunction(name: string, args: unknown[]): number {
  const values = numericValues(args);
  switch (name) {
    case 'SUM':
      return values.reduce((sum, n) => sum + n, 0);
    case 'AVERAGE': {
      if (values.length === 0) throw formulaError('#DIV/0!');
      return values.reduce((sum, n) => sum + n, 0) / values.length;
    }
    case 'COUNT':
      return values.length;
    case 'MAX': {
      if (values.length === 0) throw formulaError('#VALUE!');
      return Math.max(...values);
    }
    case 'MIN': {
      if (values.length === 0) throw formulaError('#VALUE!');
      return Math.min(...values);
    }
    default:
      throw formulaError('#NAME?');
  }
}

function add(a: unknown, b: unknown): number {
  return toNumber(a) + toNumber(b);
}

function subtract(a: unknown, b: unknown): number {
  return toNumber(a) - toNumber(b);
}

function multiply(a: unknown, b: unknown): number {
  return toNumber(a) * toNumber(b);
}

function divide(a: unknown, b: unknown): number {
  const right = toNumber(b);
  if (right === 0) throw formulaError('#DIV/0!');
  return toNumber(a) / right;
}

function rcInBounds(rc: { row: number; col: number } | null, sheet: FormulaSheet): boolean {
  return !!rc && rc.row >= 1 && rc.row <= (sheet.rowCount || 0) && rc.col >= 1 && rc.col <= (sheet.colCount || 0);
}

function collectRefs(sheet: FormulaSheet, formula: string): Set<string> {
  const refs = new Set<string>();
  if (typeof formula !== 'string' || !formula.startsWith('=')) return refs;
  const re = /\$?[A-Za-z]{1,3}\$?[1-9][0-9]*(?::\$?[A-Za-z]{1,3}\$?[1-9][0-9]*)?/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(formula))) {
    const token = m[0].replace(/\$/g, '').toUpperCase();
    if (token.includes(':')) {
      const parts = token.split(':');
      const a = cellRC(parts[0]);
      const b = cellRC(parts[1]);
      if (!rcInBounds(a, sheet) || !rcInBounds(b, sheet)) continue;
      const startRow = Math.min(a!.row, b!.row);
      const endRow = Math.max(a!.row, b!.row);
      const startCol = Math.min(a!.col, b!.col);
      const endCol = Math.max(a!.col, b!.col);
      for (let r = startRow; r <= endRow; r++) {
        for (let c = startCol; c <= endCol; c++) {
          refs.add(columnName(c) + r);
        }
      }
    } else {
      const rc = cellRC(token);
      if (rcInBounds(rc, sheet)) refs.add(columnName(rc.col) + rc.row);
    }
  }
  return refs;
}

function markCycles(sheet: FormulaSheet): Set<string> {
  const cyclic = new Set<string>();
  if (!sheet || !sheet.cells) return cyclic;
  const state: Record<string, number> = {};
  const stack: string[] = [];
  const formulaCoords = Object.keys(sheet.cells).filter((coord) => {
    const cell = sheet.cells[coord];
    return cell && typeof cell.f === 'string';
  });

  function visit(coord: string) {
    if (state[coord] === 2) return;
    if (state[coord] === 1) {
      const pos = stack.indexOf(coord);
      if (pos !== -1) {
        for (let i = pos; i < stack.length; i++) cyclic.add(stack[i]);
      }
      return;
    }
    state[coord] = 1;
    stack.push(coord);
    const cell = sheet.cells[coord];
    if (cell && typeof cell.f === 'string') {
      for (const ref of collectRefs(sheet, cell.f)) {
        const refCell = sheet.cells[ref];
        if (refCell && typeof refCell.f === 'string') visit(ref);
      }
    }
    stack.pop();
    state[coord] = 2;
  }

  for (const coord of formulaCoords) visit(coord);
  return cyclic;
}

class Parser {
  tokens: Token[];
  sheet: FormulaSheet;
  pos: number;

  constructor(tokens: Token[], sheet: FormulaSheet) {
    this.tokens = tokens;
    this.sheet = sheet;
    this.pos = 0;
  }

  peek(): Token {
    return this.tokens[this.pos];
  }

  next(): Token {
    const token = this.tokens[this.pos];
    this.pos++;
    return token;
  }

