import { useEffect, useRef, useState } from 'react';
import { apiRequest } from '../api';
import { parseClipboardText, readClipboardText } from '../spreadsheetClipboard';
import { isCoordInRange } from '../rangeUtils';

interface CellMenuState {
  coord: string;
  x: number;
  y: number;
}

interface HookCell {
  v?: string | number | boolean;
  f?: string;
}

interface HookSheet {
  id: string;
  cells?: Record<string, HookCell>;
}

interface HookWorkbook {
  id: string;
  sheets: HookSheet[];
}

interface ClipboardData {
  source: string;
  sourceSheetId: string;
  cut: boolean;
}

export function useCellPaste(
  workbook: HookWorkbook | null,
  activeSheet: HookSheet | null,
  getActiveCell: () => string,
  replaceWorkbook: (wb: HookWorkbook) => void,
  showError: (message: string | null) => void,
  updateFormulaBar: (sheet: HookSheet | null, coord: string) => void,
  selectCell: (coord: string) => void | Promise<void>,
  selectionStart: string,
  selectionEnd: string
) {
  const [cellMenu, setCellMenu] = useState<CellMenuState | null>(null);
  const clipboardRef = useRef<ClipboardData | null>(null);
  const selectionStartRef = useRef(selectionStart);
  const selectionEndRef = useRef(selectionEnd);

  selectionStartRef.current = selectionStart;
  selectionEndRef.current = selectionEnd;

  function currentSelection(): { start: string; end: string } {
    const start = selectionStartRef.current || activeCell;
    const end = selectionEndRef.current || start;
    return { start, end };
  }

  function setInternalClipboard(cut: boolean) {
    if (!workbook || !activeSheet) return;
    const { start, end } = currentSelection();
    clipboardRef.current = {
      source: `${start}:${end}`,
      sourceSheetId: activeSheet.id,
      cut,
    };
    showError(null);
  }

  function copySelection() {
    setInternalClipboard(false);
  }

  function cutSelection() {
    setInternalClipboard(true);
  }

  async function pasteRowsAt(start: string, rows: string[][]) {
    if (!workbook || !activeSheet) return;
    showError(null);
    try {
      const data = await apiRequest<{ workbook: HookWorkbook }>(
        `/api/workbooks/${workbook.id}/sheets/${activeSheet.id}/range`,
        { method: 'PATCH', body: { start, values: rows } }
      );
      replaceWorkbook(data.workbook);
      const nextSheet = data.workbook.sheets.find((s: HookSheet) => s.id === activeSheet.id) || null;
      updateFormulaBar(nextSheet, start);
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to paste');
    }
  }

  async function transferAt(coord: string, clip: ClipboardData) {
    if (!workbook || !activeSheet) return;
    showError(null);
    try {
      const data = await apiRequest<{ workbook: HookWorkbook }>(
        `/api/workbooks/${workbook.id}/sheets/${activeSheet.id}/range/transfer`,
        { method: 'POST', body: { source: clip.source, target: coord, cut: clip.cut } }
      );
      replaceWorkbook(data.workbook);
      const nextSheet = data.workbook.sheets.find((s: HookSheet) => s.id === activeSheet.id) || null;
      updateFormulaBar(nextSheet, coord);
      if (clip.cut) clipboardRef.current = null;
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to transfer range');
    }
  }

  async function pasteAtCoord(coord: string) {
    if (!workbook || !activeSheet) return;
    const clip = clipboardRef.current;
    if (clip) {
      if (clip.sourceSheetId !== activeSheet.id) {
        showError('Copy or cut is not available on this worksheet');
        return;
      }
      await transferAt(coord, clip);
      return;
    }

    let text: string;
    try {
      text = await readClipboardText();
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Could not read clipboard');
      return;
    }
    const rows = parseClipboardText(text);
    if (rows.length === 0) return;
    await pasteRowsAt(coord, rows);
  }

  function openCellContextMenu(e: { preventDefault(): void; clientX: number; clientY: number }, coord: string) {
    e.preventDefault();
    const { start, end } = currentSelection();
    if (!isCoordInRange(coord, start, end)) {
      void selectCell(coord);
    }
    setCellMenu({ coord, x: e.clientX, y: e.clientY });
  }

  function closeCellMenu() {
    setCellMenu(null);
  }

  async function pasteFromMenu() {
    if (!cellMenu) return;
    const coord = cellMenu.coord;
    setCellMenu(null);
    await pasteAtCoord(coord);
  }

  async function pasteToActive() {
    const coord = getActiveCell();
    if (!coord) return;
    await pasteAtCoord(coord);
  }

  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      const target = e.target as HTMLElement | null;
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA')) return;
      const mod = e.ctrlKey || e.metaKey;
      if (!mod) return;
      const key = e.key.toLowerCase();
      if (key === 'c') {
        e.preventDefault();
        copySelection();
      } else if (key === 'x') {
        e.preventDefault();
        cutSelection();
      } else if (key === 'v') {
        e.preventDefault();
        void pasteToActive();
      }
    }
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  });

  return { cellMenu, openCellContextMenu, closeCellMenu, pasteFromMenu, copySelection, cutSelection };
}

