import { useEffect, useRef } from 'react';
import { normalizeSelection, type SelectionRange } from '../rangeUtils';

interface UseSelectionDragArgs {
  activeSheet: { id: string } | null;
  onBegin: (sheetId: string, coord: string) => void;
  onUpdate: (sheetId: string, range: SelectionRange) => void;
  onCommit: (sheetId: string, range: SelectionRange) => void;
  getAnchor?: (sheetId: string) => string | null | undefined;
}

export function useSelectionDrag({ activeSheet, onBegin, onUpdate, onCommit, getAnchor }: UseSelectionDragArgs) {
  const dragStartRef = useRef<{ sheetId: string; coord: string } | null>(null);
  const dragCurrentRef = useRef<string | null>(null);
  const isDraggingRef = useRef(false);
  const suppressClickRef = useRef(false);
  const sheetRef = useRef(activeSheet);
  const onBeginRef = useRef(onBegin);
  const onUpdateRef = useRef(onUpdate);
  const onCommitRef = useRef(onCommit);
  const getAnchorRef = useRef(getAnchor);

  sheetRef.current = activeSheet;
  onBeginRef.current = onBegin;
  onUpdateRef.current = onUpdate;
  onCommitRef.current = onCommit;
  getAnchorRef.current = getAnchor;

  useEffect(() => {
    function handleMouseUp() {
      if (!isDraggingRef.current) return;
      const drag = dragStartRef.current;
      const current = dragCurrentRef.current;
      isDraggingRef.current = false;
      dragStartRef.current = null;
      dragCurrentRef.current = null;
      const sheet = sheetRef.current;
      if (!sheet || !drag || !current || drag.sheetId !== sheet.id) return;
      const range = normalizeSelection(drag.coord, current);
      if (range.start !== range.end) suppressClickRef.current = true;
      onCommitRef.current(drag.sheetId, range);
    }
    window.addEventListener('mouseup', handleMouseUp);
    return () => window.removeEventListener('mouseup', handleMouseUp);
  }, []);

  return {
    handleCellMouseDown(coord: string, e: { button: number; preventDefault(): void; shiftKey?: boolean }) {
      const sheet = sheetRef.current;
      if (e.button !== 0) return;
      e.preventDefault();
      suppressClickRef.current = false;
      if (!sheet) return;

      if (e.shiftKey) {
        const anchor = getAnchorRef.current ? getAnchorRef.current(sheet.id) : null;
        const anchorCoord =
          anchor && /^[A-Z]+[1-9][0-9]*$/i.test(anchor) ? anchor.toUpperCase() : null;
        const start = anchorCoord || coord;
        dragStartRef.current = { sheetId: sheet.id, coord: start };
        dragCurrentRef.current = coord;
        isDraggingRef.current = true;
        onUpdateRef.current(sheet.id, normalizeSelection(start, coord));
        return;
      }

      dragStartRef.current = { sheetId: sheet.id, coord };
      dragCurrentRef.current = coord;
      isDraggingRef.current = true;
      onBeginRef.current(sheet.id, coord);
    },
    handleCellMouseEnter(coord: string) {
      const drag = dragStartRef.current;
      const sheet = sheetRef.current;
      if (!drag || !sheet || drag.sheetId !== sheet.id || !isDraggingRef.current) return;
      dragCurrentRef.current = coord;
      onUpdateRef.current(drag.sheetId, normalizeSelection(drag.coord, coord));
    },
    shouldSuppressClick() {
      if (suppressClickRef.current) {
        suppressClickRef.current = false;
        return true;
      }
      return false;
    },
  };
}

