import { recalcSheet, type FormulaSheet } from './formulaClient';

export function cloneWorkbook<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function normalizeValue(value: unknown): string | number | boolean {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed !== '' && /^[+-]?(\d+\.?\d*|\.\d+)$/.test(trimmed)) {
      const n = Number(trimmed);
      if (Number.isFinite(n)) return n;
    }
    return value;
  }
  return String(value);
}

export function applyLocalCellValue(
  workbook: any,
  sheetId: string,
  coord: string,
  rawValue: unknown
): any {
  const wb = cloneWorkbook(workbook);
  const sheet = (wb.sheets || []).find((s: any) => s.id === sheetId);
  if (!sheet) return wb;
  const cells = sheet.cells || (sheet.cells = {});
  const cellId = String(coord).toUpperCase();
  const raw = rawValue;
  const isFormula = typeof raw === 'string' && raw.trim().startsWith('=');
  const isEmpty = raw === '' || raw === null || raw === undefined;
  if (isFormula) {
    cells[cellId] = { f: (raw as string).trim(), v: 0 };
  } else if (isEmpty) {
    delete cells[cellId];
  } else {
    cells[cellId] = { v: normalizeValue(raw) };
  }
  recalcSheet(sheet as FormulaSheet);
  return wb;
}

