export interface SelectionRange {
  start: string;
  end: string;
}

function columnToNumber(letters: string): number {
  let n = 0;
  for (let i = 0; i < letters.length; i++) {
    n = n * 26 + (letters.charCodeAt(i) - 64);
  }
  return n;
}

function columnName(n: number): string {
  let name = '';
  let value = n;
  while (value > 0) {
    const rem = (value - 1) % 26;
    name = String.fromCharCode(65 + rem) + name;
    value = Math.floor((value - 1) / 26);
  }
  return name;
}

export function parseCoord(coord: string): { row: number; col: number } | null {
  const m = /^([A-Z]+)([1-9][0-9]*)$/.exec(String(coord).toUpperCase());
  if (!m) return null;
  return { col: columnToNumber(m[1]), row: parseInt(m[2], 10) };
}

export function normalizeSelection(start: string, end: string): SelectionRange {
  const a = parseCoord(start);
  const b = parseCoord(end);
  if (!a || !b) return { start: start.toUpperCase(), end: end.toUpperCase() };
  const startCoord = columnName(Math.min(a.col, b.col)) + Math.min(a.row, b.row);
  const endCoord = columnName(Math.max(a.col, b.col)) + Math.max(a.row, b.row);
  return { start: startCoord, end: endCoord };
}

export function isCoordInRange(coord: string, start: string, end: string): boolean {
  const target = parseCoord(coord);
  const a = parseCoord(start);
  const b = parseCoord(end);
  if (!target || !a || !b) return false;
  const minRow = Math.min(a.row, b.row);
  const maxRow = Math.max(a.row, b.row);
  const minCol = Math.min(a.col, b.col);
  const maxCol = Math.max(a.col, b.col);
  return target.row >= minRow && target.row <= maxRow && target.col >= minCol && target.col <= maxCol;
}

