import { parseCoord } from './rangeUtils';

export interface ValidationRule {
  id: string;
  range: string;
  type: 'dropdown' | 'number';
  min?: number;
  max?: number;
  options?: string[];
}

interface Extents {
  startRow: number;
  endRow: number;
  startCol: number;
  endCol: number;
}

function rangeExtents(range: string): Extents | null {
  const parts = String(range).trim().toUpperCase().split(':');
  if (parts.length < 1 || parts.length > 2) return null;
  const start = parseCoord(parts[0]);
  const end = parseCoord(parts.length === 2 ? parts[1] : parts[0]);
  if (!start || !end) return null;
  return {
    startRow: Math.min(start.row, end.row),
    endRow: Math.max(start.row, end.row),
    startCol: Math.min(start.col, end.col),
    endCol: Math.max(start.col, end.col),
  };
}

function rangesOverlap(a: Extents | null, b: Extents | null): boolean {
  if (!a || !b) return false;
  return (
    a.startRow <= b.endRow &&
    a.endRow >= b.startRow &&
    a.startCol <= b.endCol &&
    a.endCol >= b.startCol
  );
}

export function findValidationForCell(sheet: any, coord: string): ValidationRule | null {
  const rules = Array.isArray(sheet?.validations) ? sheet.validations : [];
  const cellExtents = rangeExtents(coord);
  return (
    rules.find((rule: any) => {
      const ruleExtents = rangeExtents(rule.range);
      return rangesOverlap(ruleExtents, cellExtents);
    }) || null
  );
}

export function findValidationForSelection(sheet: any, range: string): ValidationRule | null {
  const rules = Array.isArray(sheet?.validations) ? sheet.validations : [];
  const selectionExtents = rangeExtents(range);
  return (
    rules.find((rule: any) => {
      const ruleExtents = rangeExtents(rule.range);
      return rangesOverlap(ruleExtents, selectionExtents);
    }) || null
  );
}

